// Estado de las notificaciones en este equipo: 'activo', 'disponible'
// (se pueden pedir), 'bloqueado', 'iosNoInstalado' o 'nosoportado'.
async function estadoPushEquipo() {
  const ua = window.navigator.userAgent || '';
  const esIOS = /iPad|iPhone|iPod/.test(ua) && !window.MSStream;
  const instalada = window.matchMedia('(display-mode: standalone)').matches
    || window.navigator.standalone === true;
  if (!('Notification' in window) || !('serviceWorker' in navigator) || !('PushManager' in window)) {
    return esIOS && !instalada ? 'iosNoInstalado' : 'nosoportado';
  }
  if (Notification.permission === 'denied') return 'bloqueado';
  try {
    const reg = await navigator.serviceWorker.ready;
    const sub = await reg.pushManager.getSubscription();
    return sub ? 'activo' : 'disponible';
  } catch { return 'disponible'; }
}

// Tipo de celular y si abrió la app desde el navegador de Instagram,
// TikTok o Facebook (ahí no llegan avisos: hay que abrirla en Chrome o
// Safari).
function equipoDelAlumno() {
  const ua = window.navigator.userAgent || '';
  const iphone = /iPad|iPhone|iPod/.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1);
  const dispositivo = iphone ? 'iphone' : /Android/i.test(ua) ? 'android'
    : /Windows|Macintosh|Linux|CrOS/.test(ua) ? 'computadora' : 'otro';
  const instalada = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;
  const app = /FBAN|FBAV|FB_IAB|FBIOS|Messenger/i.test(ua) ? 'Facebook'
    : /Instagram/i.test(ua) ? 'Instagram'
    : /musical_ly|Bytedance|TikTok|trill|aweme/i.test(ua) ? 'TikTok'
    // Otras apps que abren páginas por dentro: en Android se ven como
    // "; wv)"; en iPhone, sin la palabra "Safari" (y sin estar instalada).
    : (/Android/i.test(ua) && /; wv\)/.test(ua)) || (iphone && !instalada && !/Safari\//.test(ua) && !/CriOS|FxiOS|EdgiOS/.test(ua)) ? 'otra app'
    : null;
  return { dispositivo, navegadorInterno: !!app, app, instalada };
}

// Estado de avisos del equipo -> lo que se guarda en la tabla
// estado_avisos, para que Jonah vea en su panel quién no recibe avisos,
// por qué y en qué celular (y le escriba con los pasos justos).
const ESTADO_AVISOS_DB = {
  activo: 'activo', iosNoInstalado: 'ios_sin_instalar', bloqueado: 'bloqueado',
  disponible: 'sin_activar', nosoportado: 'no_soportado',
};

function anotarEstadoAvisos(estado, username) {
  const valor = ESTADO_AVISOS_DB[estado];
  if (!valor || !username) return;
  const { dispositivo, navegadorInterno, instalada } = equipoDelAlumno();
  // Una vez al día como mucho, salvo que cambie algo.
  const firma = [username, valor, dispositivo, navegadorInterno, instalada].join('|');
  try {
    const previa = JSON.parse(localStorage.getItem('jb-estado-avisos') || 'null');
    if (previa?.firma === firma && Date.now() - previa.en < 86400000) return;
    localStorage.setItem('jb-estado-avisos', JSON.stringify({ firma, en: Date.now() }));
  } catch {}
  supabase.from('estado_avisos').upsert({
    username, dispositivo, estado: valor, instalada, navegador_interno: navegadorInterno,
    actualizado_en: new Date().toISOString(),
  }, { onConflict: 'username' }).then(() => {}, () => {});
}

// Pide el permiso del navegador, crea la suscripción y la guarda para
// el alumno. Devuelve el estado final ('activo', 'bloqueado' o 'disponible').
async function activarPushAlumno(username) {
  const final = await activarPushAlumnoInterno(username);
  anotarEstadoAvisos(final, username);
  return final;
}

async function activarPushAlumnoInterno(username) {
  const permiso = await Notification.requestPermission();
  if (permiso !== 'granted') return permiso === 'denied' ? 'bloqueado' : 'disponible';
  const reg = await navigator.serviceWorker.ready;
  let sub = await reg.pushManager.getSubscription();
  if (!sub) {
    sub = await reg.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: base64ToUint8(VAPID_PUBLIC),
    });
  }
  const j = sub.toJSON();
  await supabase.from('push_subs').upsert({
    username, endpoint: j.endpoint, p256dh: j.keys.p256dh, auth: j.keys.auth, activa: true,
  }, { onConflict: 'endpoint' });
  return 'activo';
}

/* La rayita de arriba de las hojas que suben desde abajo (solo en el
   celular). Si la hoja se puede cerrar tocando afuera, también se cierra
   deslizando la rayita hacia abajo. */
function AsaHoja({ onCerrar }) {
  const inicio = useRef(null);
  return (
    <div className="sm:hidden -mt-3 mb-3 pt-1 pb-2 flex justify-center touch-none"
      onTouchStart={e => { inicio.current = e.touches[0].clientY; }}
      onTouchEnd={e => {
        const dy = inicio.current === null ? 0 : e.changedTouches[0].clientY - inicio.current;
        inicio.current = null;
        if (onCerrar && dy > 60) onCerrar();
      }}>
      <div className="w-10 h-1 rounded-full bg-zinc-700" />
    </div>
  );
}

// Después de registrar una comida es el mejor momento para ofrecer los
// recordatorios: el alumno ya vio para qué sirve la app. Antes solo se
// pedían en la bienvenida, y el banner del inicio no se ve durante la
// prueba gratis (ahí va el de la prueba). Se ofrece una sola vez.
function NotifTrasComidaModal({ username, onClose }) {
  const [trabajando, setTrabajando] = useState(false);
  const [resultado, setResultado] = useState(null);

  async function activar() {
    setTrabajando(true);
    let estado = 'disponible';
    try { estado = await activarPushAlumno(username); } catch {}
    setTrabajando(false);
    if (estado === 'activo') {
      setResultado('activo'); setTimeout(onClose, 1800);
      // El saludo de Jonah (antes se mandaba al activarlos en la guía de
      // bienvenida, que ya no los pide).
      supabase.auth.getSession().then(({ data: { session } }) => fetch('/api/bienvenida-push', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${session?.access_token || ''}` },
        body: JSON.stringify({ username }),
      })).catch(() => {});
    }
    else if (estado === 'bloqueado') setResultado('bloqueado');
    else onClose();
  }

  return (
    <div className="fixed inset-0 bg-black/80 flex items-end sm:items-center justify-center sm:p-4 z-50">
      <div className="max-h-[90vh] overflow-y-auto pb-[max(1.5rem,env(safe-area-inset-bottom))] sm:pb-6 bg-zinc-900 border border-orange-500/40 rounded-t-3xl sm:rounded-2xl max-w-sm w-full p-6 text-center">
        <AsaHoja />
        <div className="w-16 h-16 rounded-full bg-orange-500/15 border border-orange-500/30 flex items-center justify-center text-4xl mx-auto mb-3">
          {resultado === 'activo' ? '✅' : '🦍'}
        </div>
        {resultado === 'activo' ? (
          <h2 className="jb-display text-xl text-zinc-50">¡LISTO! TE AVISARÉ</h2>
        ) : resultado === 'bloqueado' ? (
          <>
            <h2 className="jb-display text-xl text-zinc-50 mb-3">ESTÁN BLOQUEADAS</h2>
            <p className="jb-body text-sm text-zinc-300 mb-5">Tu navegador bloqueó las notificaciones de esta página. Puedes activarlas en los ajustes del navegador cuando quieras.</p>
            <button onClick={onClose} className={btnPrimary + ' w-full'}>Entendido</button>
          </>
        ) : (
          <>
            <h2 className="jb-display text-xl text-zinc-50 mb-3">¡COMIDA REGISTRADA! 💪</h2>
            <p className="jb-body text-sm text-zinc-300 mb-2">
              ¿Activamos tus avisos? Solo lo importante, sin spam:
            </p>
            <ul className="mb-5 flex flex-col gap-1 text-left">
              {BENEFICIOS_AVISOS.map(([e, t]) => (
                <li key={t} className="jb-body text-xs text-zinc-300 flex items-start gap-2"><span>{e}</span><span>{t}</span></li>
              ))}
            </ul>
            <button onClick={activar} disabled={trabajando} className={btnPrimary + ' w-full mb-2'}>
              {trabajando ? <Loader2 className="animate-spin" size={18} /> : '🔔 Sí, activar avisos'}
            </button>
            <button onClick={onClose} className="jb-body text-sm text-zinc-500 hover:text-zinc-300 w-full py-2">
              Ahora no
            </button>
          </>
        )}
      </div>
    </div>
  );
}

