function Dashboard({ form, setForm, results, mealPlan, targets, username, onVerComposicion, onIrProgreso }) {
  const pesoActual = Number(form.peso) || 0;
  const pesoInicial = form.pesoInicial === null || form.pesoInicial === undefined || form.pesoInicial === '' ? null : Number(form.pesoInicial);
  const pesoObjetivo = form.pesoObjetivo === null || form.pesoObjetivo === undefined || form.pesoObjetivo === '' ? null : Number(form.pesoObjetivo);

  let progreso = null;
  if (pesoInicial && pesoObjetivo && pesoInicial !== pesoObjetivo) {
    progreso = ((pesoInicial - pesoActual) / (pesoInicial - pesoObjetivo)) * 100;
    progreso = Math.max(Math.min(progreso, 100), 0);
  }

  const totalsHoy = { kcal: 0, protein: 0 };
  Object.values(mealPlan.meals).forEach(entries => entries.forEach(en => {
    const m = entryMacros(en);
    totalsHoy.kcal += m.kcal; totalsHoy.protein += m.protein;
  }));

  return (
    <div className="flex flex-col gap-6 min-w-0">
      <BeastScoreCard totalsHoy={totalsHoy} targets={targets} username={username} />

      <InvitaAmigoCard username={username} />

      <button onClick={onVerComposicion}
        className="bg-zinc-900 border border-zinc-800 hover:border-orange-500/50 rounded-xl p-4 flex items-center gap-3 text-left transition-colors">
        <Flame className="text-amber-400 shrink-0" size={18} />
        <p className="jb-body text-sm text-zinc-300 flex-1">
          {!results.basicos ? (
            <span className="text-zinc-100 font-semibold">Completa tus datos básicos para calcular tus calorías</span>
          ) : results.cinta ? (
            <><span className="text-zinc-100 font-semibold">{results.bf.toFixed(1)}% grasa</span> · IMC {results.bmi.toFixed(1)} · {results.bfCat}</>
          ) : (
            <><span className="text-zinc-100 font-semibold">IMC {results.bmi.toFixed(1)}</span> · 📏 Mide tu % de grasa (opcional)</>
          )}
        </p>
        <ChevronRight className="text-zinc-600 shrink-0" size={16} />
      </button>

      {progreso !== null ? (
        <button onClick={onIrProgreso} className="bg-zinc-900 border border-zinc-800 hover:border-orange-500/50 rounded-2xl p-4 text-left transition-colors">
          <div className="flex items-center justify-between mb-2">
            <span className="jb-display text-sm text-zinc-200">MI OBJETIVO DE PESO</span>
            <span className="jb-display text-lg text-orange-500">{Math.round(progreso)}%</span>
          </div>
          <div className="w-full h-2.5 bg-zinc-800 rounded-full overflow-hidden mb-2">
            <div className="h-full bg-gradient-to-r from-orange-600 to-orange-400 rounded-full transition-all" style={{ width: `${progreso}%` }} />
          </div>
          <p className="jb-body text-xs text-zinc-500">
            {pesoInicial} kg → {pesoObjetivo} kg · hoy {pesoActual} kg ·{' '}
            {progreso >= 100 ? '¡Llegaste a tu meta!' : `te faltan ${Math.abs(pesoActual - pesoObjetivo).toFixed(1)} kg`}
          </p>
        </button>
      ) : (
        <button onClick={() => onIrProgreso('meta-peso')}
          className="bg-zinc-900 border border-zinc-800 hover:border-orange-500/50 rounded-xl p-4 flex items-center gap-3 text-left transition-colors">
          <Target className="text-orange-500 shrink-0" size={18} />
          <p className="jb-body text-sm text-zinc-300 flex-1"><span className="text-zinc-100 font-semibold">Define tu meta de peso</span> para ver cuánto avanzas</p>
          <ChevronRight className="text-zinc-600 shrink-0" size={16} />
        </button>
      )}
    </div>
  );
}

/* Una sola regla en toda la app para "cumpliste tu meta del día": entre el
   85% y el 115% de tus calorías (igual que Tu semana, Progreso, el coach y
   el Beast Score). Debajo: te falta; encima: te pasaste. Verde = cumpliste
   (como el ✓ de las comidas registradas). */
const META_MIN = 0.85, META_MAX = 1.15;
function estadoMeta(consumido, meta) {
  if (!(meta > 0) || !(consumido > 0)) return 'falta';
  const r = consumido / meta;
  return r < META_MIN ? 'falta' : r <= META_MAX ? 'cumplido' : 'pasado';
}

function CalorieStatus({ consumed, target }) {
  if (!target) return null;
  const ratio = consumed / target;
  let color, bg, border, text;
  const estado = estadoMeta(consumed, target);
  if (consumed === 0) {
    return null;
  } else if (estado === 'falta') {
    color = 'text-orange-400'; bg = 'bg-orange-950/30'; border = 'border-orange-800/40';
    text = `Vas bien — te faltan unas ${Math.round(target * META_MIN - consumed)} kcal para entrar en tu meta del día.`;
  } else if (estado === 'cumplido') {
    color = 'text-emerald-400'; bg = 'bg-emerald-950/40'; border = 'border-emerald-800/50';
    text = '¡Cumpliste tu meta de hoy! 💪 Así se hace, comida a comida.';
  } else {
    color = 'text-amber-400'; bg = 'bg-amber-950/40'; border = 'border-amber-800/50';
    text = 'Pasaste tu meta de hoy. Un día no define tu progreso — sigue normal mañana, sin compensar.';
  }
  const pctFill = Math.min(ratio * 100, 100);
  return (
    <div className={`${bg} ${border} border rounded-xl p-3 mb-4`}>
      <div className="flex items-center justify-between mb-2">
        <span className={`jb-display text-sm ${color}`}>{Math.round(consumed)} / {Math.round(target)} kcal</span>
        <span className="jb-body text-[11px] text-zinc-400">{Math.round(ratio * 100)}%</span>
      </div>
      <div className="w-full h-2 bg-zinc-800 rounded-full overflow-hidden">
        <div className={`h-full rounded-full ${estado === 'falta' ? 'bg-orange-500' : estado === 'cumplido' ? 'bg-emerald-500' : 'bg-amber-500'}`}
          style={{ width: `${pctFill}%` }} />
      </div>
      <p className="jb-body text-xs text-zinc-400 mt-2">{text}</p>
    </div>
  );
}

