// Medidor fijo arriba de Comidas: anillo con lo que queda del día y
// barras de proteína, carbos y grasas. Se queda pegado bajo el
// encabezado mientras el alumno baja.
function MedidorComidas({ totals, targetKcal, objP, objC, objF, fijo = true }) {
  const [topHeader, setTopHeader] = useState(64);
  const [pulso, setPulso] = useState(0);
  const kcalPrevia = useRef(totals.kcal);

  useEffect(() => {
    const medir = () => { const h = document.querySelector('header'); if (h) setTopHeader(h.offsetHeight); };
    medir();
    window.addEventListener('resize', medir);
    return () => window.removeEventListener('resize', medir);
  }, []);

  // Destello del anillo cada vez que se suma comida.
  useEffect(() => {
    if (totals.kcal > kcalPrevia.current + 0.5) setPulso(p => p + 1);
    kcalPrevia.current = totals.kcal;
  }, [totals.kcal]);

  const objetivo = Math.max(1, targetKcal || 0);
  const restante = Math.round(objetivo - totals.kcal);
  const pasado = restante < 0;
  const avance = Math.min(1, totals.kcal / objetivo);
  const R = 32, C = 2 * Math.PI * R;
  const estado = estadoMeta(totals.kcal, objetivo);
  const colorAnillo = estado === 'pasado' ? '#f59e0b' : estado === 'cumplido' ? '#10b981' : '#E8590C';
  const macros = [
    ['Proteína', totals.protein, objP],
    ['Carbos', totals.carbs, objC],
    ['Grasas', totals.fat, objF],
  ];

  return (
    <div className={fijo ? 'sticky z-10 -mx-6 px-6 pt-2 pb-3 bg-zinc-950/95 backdrop-blur-sm border-b border-zinc-800/80' : ''} style={fijo ? { top: topHeader } : undefined}>
      <div className="flex items-center gap-4">
        <div key={pulso} className={`relative w-[84px] h-[84px] shrink-0 ${pulso ? 'jbm-pulso' : ''}`}>
          <svg viewBox="0 0 84 84" className="w-full h-full -rotate-90">
            <circle cx="42" cy="42" r={R} fill="none" stroke="#2a211a" strokeWidth="8" />
            <circle cx="42" cy="42" r={R} fill="none" stroke={colorAnillo} strokeWidth="8" strokeLinecap="round"
              strokeDasharray={C} strokeDashoffset={C * (1 - avance)}
              style={{ transition: 'stroke-dashoffset .7s cubic-bezier(.2,.8,.3,1), stroke .3s' }} />
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center leading-none">
            <span className={`jb-display text-xl tabular-nums ${estado === 'pasado' ? 'text-amber-400' : estado === 'cumplido' ? 'text-emerald-400' : 'text-zinc-50'}`}>
              <AnimatedNumber value={Math.abs(restante)} />
            </span>
            <span className="jb-body text-[10px] text-zinc-400 mt-0.5">{pasado ? 'kcal de más' : 'kcal quedan'}</span>
          </div>
        </div>
        <div className="flex-1 min-w-0 flex flex-col gap-1.5">
          <p className="jb-body text-[11px] text-zinc-400 tabular-nums">
            <span className="text-zinc-200 font-semibold">{Math.round(totals.kcal)}</span> de {Math.round(objetivo)} kcal
          </p>
          {macros.map(([nombre, val, obj]) => {
            const pct = obj > 0 ? Math.min(1, val / obj) : 0;
            const excedido = obj > 0 && val > obj * META_MAX;
            return (
              <div key={nombre}>
                <div className="flex justify-between jb-body text-[10px] text-zinc-400 mb-0.5 tabular-nums">
                  <span>{nombre}</span><span className={excedido ? 'text-amber-400' : ''}>{Math.round(val)}/{Math.round(obj)} g</span>
                </div>
                <div className="h-1.5 rounded-full bg-zinc-800 overflow-hidden">
                  <div className={`h-full rounded-full ${excedido ? 'bg-amber-500' : 'bg-orange-500'}`} style={{ width: `${pct * 100}%`, transition: 'width .7s cubic-bezier(.2,.8,.3,1)' }} />
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* CÓDIGO DE BARRAS                                                     */
/* Cámara → código → producto (tabla productos u Open Food Facts, en la */
/* función reconocer-comida). Si no está, el alumno le toma foto a la   */
/* tabla nutricional y la IA la lee; se guarda para todos.              */
/* ------------------------------------------------------------------ */

const FORMATOS_CODIGO = ['ean_13', 'ean_8', 'upc_a', 'upc_e'];

// Láser del escáner: una línea naranja con brillo que barre el recuadro de
// arriba abajo, esquinas que laten y un destello al leer el código.
const ESTILOS_LASER = `
@keyframes jbl-barrido { 0% { top: 6%; } 50% { top: 90%; } 100% { top: 6%; } }
@keyframes jbl-esquina { 0%, 100% { opacity: .6; } 50% { opacity: 1; } }
@keyframes jbl-leido { 0% { opacity: 0; transform: scale(.85); } 30% { opacity: 1; transform: scale(1.04); } 100% { opacity: 1; transform: scale(1); } }
.jbl-laser { animation: jbl-barrido 1.6s ease-in-out infinite; }
.jbl-esquina { animation: jbl-esquina 1.1s ease-in-out infinite; }
.jbl-leido { animation: jbl-leido .35s cubic-bezier(.2,.8,.3,1) both; }
`;

// Lector: el del navegador si lo tiene (Chrome de Android); si no (iPhone),
// uno que se descarga solo cuando hace falta.
async function crearLectorCodigo() {
  try {
    if ('BarcodeDetector' in window) {
      const soportados = await window.BarcodeDetector.getSupportedFormats();
      if (FORMATOS_CODIGO.some(f => soportados.includes(f))) return new window.BarcodeDetector({ formats: FORMATOS_CODIGO });
    }
  } catch {}
  const [{ BarcodeDetector, prepareZXingModule }, { default: urlWasm }] = await Promise.all([
    import('barcode-detector/ponyfill'),
    import('zxing-wasm/reader/zxing_reader.wasm?url'),
  ]);
  // El lector se sirve desde nuestra propia app, no desde internet.
  prepareZXingModule({ overrides: { locateFile: (ruta, prefijo) => (ruta.endsWith('.wasm') ? urlWasm : prefijo + ruta) } });
  return new BarcodeDetector({ formats: FORMATOS_CODIGO });
}

async function llamarProductos(body) {
  const { data, error } = await supabase.functions.invoke('reconocer-comida', { body });
  if (error) {
    let motivo = '';
    try { motivo = (await error.context.json())?.error || ''; } catch {}
    throw new Error(motivo || 'No se pudo conectar. Intenta de nuevo.');
  }
  return data || {};
}

function EscanearCodigoModal({ meal, onCerrar, onAgregar, onEscribir }) {
  const { premium } = usePremium();
  const [estado, setEstado] = useState('camara'); // camara | sin_camara | buscando | producto | no_encontrado | leyendo | confirmar | limite | error
  const [codigo, setCodigo] = useState('');
  const [tardando, setTardando] = useState(false); // la cámara lleva un rato sin leer: se muestran consejos
  const [leido, setLeido] = useState(''); // destello "✓ código leído" antes de buscar
  const [producto, setProducto] = useState(null); // fila de productos (o lo leído de la etiqueta)
  const [nombreNuevo, setNombreNuevo] = useState('');
  const [marcaNueva, setMarcaNueva] = useState('');
  const [unidad, setUnidad] = useState('porción');
  const [cantidad, setCantidad] = useState(1);
  const [mensaje, setMensaje] = useState('');
  const [guardando, setGuardando] = useState(false);
  const videoRef = useRef(null);
  const streamRef = useRef(null);

  function apagarCamara() {
    try { streamRef.current?.getTracks().forEach(t => t.stop()); } catch {}
    streamRef.current = null;
  }

  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prev; apagarCamara(); };
  }, []);

  // Cámara + lectura continua mientras se está en "camara".
  useEffect(() => {
    if (estado !== 'camara') return;
    let cancelado = false;
    let timer = null;
    setTardando(false);
    setLeido('');
    const aviso = setTimeout(() => { if (!cancelado) setTardando(true); }, 6000);
    (async () => {
      try {
        if (!navigator.mediaDevices?.getUserMedia) throw new Error('sin cámara');
        // Alta resolución: con la cámara por defecto (640×480 en iPhone) las
        // barras salen demasiado finas y el código casi nunca se lee.
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: { ideal: 'environment' }, width: { ideal: 1920 }, height: { ideal: 1080 } }, audio: false,
        });
        if (cancelado) { stream.getTracks().forEach(t => t.stop()); return; }
        streamRef.current = stream;
        try { await stream.getVideoTracks()[0]?.applyConstraints({ advanced: [{ focusMode: 'continuous' }] }); } catch {}
        const video = videoRef.current;
        if (!video) return;
        video.srcObject = stream;
        await video.play().catch(() => {});
        const lector = await crearLectorCodigo();
        let fallos = 0;
        let anterior = '';
        const mirar = async () => {
          if (cancelado) return;
          try {
            if (video.readyState >= 2) {
              const hallados = await lector.detect(video);
              fallos = 0;
              // Se prefiere el código largo (EAN-13 / UPC-A) y solo se acepta
              // cuando sale igual en dos lecturas seguidas: con el empaque
              // arrugado o de costado, el lector a veces "ve" un código
              // corto que no existe.
              const valores = (hallados || []).map(h => String(h.rawValue || '').replace(/\D/g, '')).filter(v => v.length >= 8);
              const valor = valores.sort((a, b) => b.length - a.length)[0] || '';
              if (valor && valor === anterior) {
                vibrar(30); setLeido(valor);
                setTimeout(() => { apagarCamara(); buscar(valor); }, 450);
                return;
              }
              anterior = valor;
            }
          } catch {
            // Si el lector en vivo no funciona en este celular, se pasa a la foto del código.
            if (++fallos >= 12) { apagarCamara(); setMensaje('No pudimos leer el código con la cámara en vivo.'); setEstado('sin_camara'); return; }
          }
          timer = setTimeout(mirar, 150);
        };
        mirar();
      } catch {
        if (!cancelado) { apagarCamara(); setMensaje('No pudimos abrir la cámara en vivo.'); setEstado('sin_camara'); }
      }
    })();
    return () => { cancelado = true; clearTimeout(timer); clearTimeout(aviso); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [estado]);

  function mostrarProducto(p) {
    setProducto(p);
    const conPorcion = Number(p.porcion_g) > 0;
    setUnidad(conPorcion ? 'porción' : 'gramos');
    setCantidad(conPorcion ? 1 : 100);
    setEstado('producto');
  }

  async function buscar(valor) {
    setCodigo(valor);
    setEstado('buscando');
    try {
      const r = await llamarProductos({ accion: 'buscar_codigo', codigo: valor });
      if (r.encontrado && r.producto) mostrarProducto(r.producto);
      else { setMensaje(r.error || ''); setEstado('no_encontrado'); }
    } catch (e) { setMensaje(e.message); setEstado('error'); }
  }

  // Plan B cuando la cámara en vivo no lee: una foto normal del código.
  async function fotoCodigo(e) {
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file) return;
    apagarCamara();
    setEstado('buscando');
    try {
      const blob = await comprimirImagen(file, 1600, 0.92);
      let valor = '';
      try {
        const [lector, imagen] = await Promise.all([crearLectorCodigo(), createImageBitmap(blob)]);
        const hallados = await lector.detect(imagen);
        valor = (hallados || []).map(h => String(h.rawValue || '').replace(/\D/g, '')).filter(v => v.length >= 8).sort((a, b) => b.length - a.length)[0] || '';
      } catch {}
      // Si las barras no se leen, la IA lee los números impresos debajo.
      if (!valor) {
        const base64 = await new Promise((ok, mal) => {
          const reader = new FileReader();
          reader.onload = () => ok(String(reader.result).split(',')[1] || '');
          reader.onerror = mal;
          reader.readAsDataURL(blob);
        });
        const r = await llamarProductos({ accion: 'leer_codigo_foto', imagenBase64: base64, mimeType: 'image/jpeg' });
        valor = r.codigo || '';
      }
      if (valor) { vibrar(30); buscar(valor); return; }
      setMensaje('No pudimos leer el código en la foto. Tómala más cerca, que se vean bien las barras y los números, y sin brillo.');
    } catch {
      setMensaje('No pudimos leer el código en la foto. Intenta con otra.');
    }
    setEstado('sin_camara');
  }

  async function fotoEtiqueta(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setEstado('leyendo');
    try {
      const blob = await comprimirImagen(file, 1600, 0.9);
      const base64 = await new Promise((ok, mal) => {
        const reader = new FileReader();
        reader.onload = () => ok(String(reader.result).split(',')[1] || '');
        reader.onerror = mal;
        reader.readAsDataURL(blob);
      });
      const r = await llamarProductos({ accion: 'leer_etiqueta', codigo, imagenBase64: base64, mimeType: 'image/jpeg' });
      if (r.error === 'limite_alcanzado') { setEstado('limite'); return; }
      if (r.error === 'premium') { setMensaje('Leer la tabla nutricional con foto es Premium.'); setEstado('no_encontrado'); return; }
      if (r.error || !r.producto) { setMensaje(r.error || 'No pudimos leer la etiqueta.'); setEstado('no_encontrado'); return; }
      setProducto(r.producto);
      setNombreNuevo(r.producto.nombre || '');
      setMarcaNueva(r.producto.marca || '');
      setEstado('confirmar');
    } catch (err) { setMensaje(err.message); setEstado('no_encontrado'); }
  }

  async function guardarLeido() {
    if (!nombreNuevo.trim()) return;
    setGuardando(true);
    try {
      const r = await llamarProductos({ accion: 'guardar_producto', codigo, producto: { ...producto, nombre: nombreNuevo.trim(), marca: marcaNueva.trim() } });
      if (r.error || !r.producto) throw new Error(r.error || 'No se pudo guardar.');
      mostrarProducto(r.producto);
    } catch (err) { setMensaje(err.message); }
    setGuardando(false);
  }

  // Si el alumno cierra con la etiqueta ya leída y un nombre, el producto se
  // guarda igual (antes se perdía si no tocaba "Guardar").
  function cerrar() {
    if (estado === 'confirmar' && producto && codigo && nombreNuevo.trim()) {
      llamarProductos({ accion: 'guardar_producto', codigo, producto: { ...producto, nombre: nombreNuevo.trim(), marca: marcaNueva.trim() } }).catch(() => {});
    }
    onCerrar();
  }

  const gramosPorUnidad = unidad === 'porción' ? Number(producto?.porcion_g) || 0 : 1;
  const gramos = cantidad * gramosPorUnidad;
  const macros = producto ? {
    kcal: Number(producto.kcal) * gramos / 100, protein: Number(producto.proteina) * gramos / 100,
    carbs: Number(producto.carbos) * gramos / 100, fat: Number(producto.grasa) * gramos / 100,
  } : null;
  const paso = unidad === 'porción' ? 0.5 : 10;

  function agregar() {
    const key = agregarProductoAFoods(producto);
    onAgregar({ id: uid(), foodKey: key, unit: unidad, qty: cantidad });
    showToast(`${producto.nombre} agregado a ${meal.toLowerCase()}`);
    onCerrar();
  }

  // Foto normal del código (plan B de la cámara en vivo). Destacado cuando
  // la cámara ya falló o lleva rato sin leer; si no, discreto.
  const botonFotoCodigo = (destacado) => (
    <label className={(destacado ? btnPrimary + ' py-3' : btnGhost + ' py-2.5 text-sm') + ' w-full cursor-pointer'}>
      <Camera size={16} /> Tomar foto al código
      <input type="file" accept="image/*" capture="environment" className="hidden" onChange={fotoCodigo} />
    </label>
  );
  // Por si ya le tomó foto antes (en la tienda) o la cámara no abre.
  const galeriaCodigo = (
    <label className="block jb-body text-xs text-zinc-500 hover:text-orange-400 text-center py-2 cursor-pointer">
      🖼️ Subir de mi galería
      <input type="file" accept="image/*" className="hidden" onChange={fotoCodigo} />
    </label>
  );

  const botonFotoEtiqueta = (
    <>
      <label className={btnPrimary + ' w-full py-3 cursor-pointer'}>
        <Camera size={16} /> Tomar foto a la tabla nutricional
        <input type="file" accept="image/*" capture="environment" className="hidden" onChange={fotoEtiqueta} />
      </label>
      <label className="block jb-body text-xs text-zinc-500 hover:text-orange-400 text-center py-2 cursor-pointer">
        🖼️ Subir de mi galería
        <input type="file" accept="image/*" className="hidden" onChange={fotoEtiqueta} />
      </label>
    </>
  );

  return (
    <div className="fixed inset-0 bg-black/80 flex items-end sm:items-center justify-center sm:p-4 z-50" onClick={cerrar}>
      <div className="max-h-[90vh] overflow-y-auto pb-[max(1.5rem,env(safe-area-inset-bottom))] sm:pb-6 bg-zinc-900 border border-orange-500/40 rounded-t-3xl sm:rounded-2xl max-w-md w-full p-5" onClick={e => e.stopPropagation()}>
        <AsaHoja onCerrar={cerrar} />
        <style>{ESTILOS_ESCANER + ESTILOS_LASER}</style>
        <div className="flex items-center justify-between mb-4">
          <h2 className="jb-display text-base text-orange-500 flex items-center gap-2"><ScanBarcode size={18} /> CÓDIGO DE BARRAS</h2>
          <button onClick={cerrar} className="text-zinc-500 hover:text-zinc-300 p-2.5 -m-1.5" aria-label="Cerrar"><X size={18} /></button>
        </div>

        {estado === 'camara' && (
          <div>
            <div className="relative w-full aspect-[4/3] bg-zinc-950 rounded-xl overflow-hidden border border-orange-500/30 mb-3">
              <video ref={videoRef} playsInline muted className="absolute inset-0 w-full h-full object-cover" />
              {/* Recuadro: fuera de él se oscurece; dentro, el láser barre el código */}
              <div className="absolute left-[10%] right-[10%] top-1/2 -translate-y-1/2 h-[42%] rounded-lg pointer-events-none overflow-hidden"
                style={{ boxShadow: '0 0 0 999px rgba(9,7,5,.55)' }}>
                {!leido && (
                  <div className="jbl-laser absolute left-0 right-0 h-[3px] rounded-full"
                    style={{ background: 'linear-gradient(90deg, transparent, #FF7020 12%, #FFB27A 50%, #FF7020 88%, transparent)', boxShadow: '0 0 10px 2px rgba(255,112,32,.85), 0 0 26px 6px rgba(232,89,12,.45)' }} />
                )}
              </div>
              {[['top-[29%] left-[10%]', 'border-t-[3px] border-l-[3px] rounded-tl-lg'], ['top-[29%] right-[10%]', 'border-t-[3px] border-r-[3px] rounded-tr-lg'],
                ['bottom-[29%] left-[10%]', 'border-b-[3px] border-l-[3px] rounded-bl-lg'], ['bottom-[29%] right-[10%]', 'border-b-[3px] border-r-[3px] rounded-br-lg']].map(([pos, borde]) => (
                <div key={pos} className={`jbl-esquina absolute ${pos} w-7 h-7 ${borde} ${leido ? 'border-zinc-50' : 'border-orange-500'} pointer-events-none`} />
              ))}
              <span className="absolute top-2.5 left-1/2 -translate-x-1/2 jb-display text-[10px] tracking-[0.2em] text-orange-400 bg-zinc-950/80 border border-orange-500/40 rounded-full px-2.5 py-0.5 pointer-events-none">
                {leido ? 'CÓDIGO LEÍDO' : 'ESCANEANDO'}
              </span>
              {leido && (
                <div className="jbl-leido absolute inset-0 flex flex-col items-center justify-center bg-orange-500/20 pointer-events-none">
                  <span className="w-14 h-14 rounded-full bg-orange-500 text-zinc-950 flex items-center justify-center shadow-[0_0_30px_rgba(255,112,32,.7)]"><Check size={30} strokeWidth={3} /></span>
                  <span className="jb-body text-sm text-zinc-50 font-semibold tabular-nums tracking-wider mt-2 bg-zinc-950/70 rounded-full px-3 py-0.5">{leido}</span>
                </div>
              )}
            </div>
            <p className="jb-body text-sm text-zinc-300 text-center mb-3">Apunta al código de barras del producto. Se lee solo.</p>
            {tardando && (
              <div className="bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2.5 mb-3 jb-body text-xs text-zinc-400">
                <p className="text-zinc-200 font-semibold mb-0.5">¿No lo lee?</p>
                Acerca el celular hasta que las barras llenen el recuadro, estira el empaque si está arrugado y evita el brillo de la luz.
              </div>
            )}
            {botonFotoCodigo(tardando)}
            {galeriaCodigo}
            <button onClick={onEscribir} className="w-full jb-body text-xs text-zinc-500 hover:text-zinc-300 mt-3 underline">Buscarlo por su nombre</button>
          </div>
        )}

        {estado === 'sin_camara' && (
          <div>
            {mensaje && <p className="jb-body text-sm text-zinc-200 mb-1">{mensaje}</p>}
            <p className="jb-body text-sm text-zinc-400 mb-4">Tómale una <span className="text-orange-400 font-semibold">foto al código de barras</span>, de cerca y sin brillo, y lo leemos desde la foto.</p>
            {botonFotoCodigo(true)}
            {galeriaCodigo}
            <button onClick={() => { setMensaje(''); setEstado('camara'); }} className={btnGhost + ' w-full py-2.5 text-sm mt-2'}>Volver a la cámara en vivo</button>
            <button onClick={onEscribir} className="w-full jb-body text-xs text-zinc-500 hover:text-zinc-300 mt-3 underline">Buscarlo por su nombre</button>
          </div>
        )}

        {(estado === 'buscando' || estado === 'leyendo') && (
          <div className="flex flex-col items-center gap-3 py-8">
            <Loader2 className="animate-spin text-orange-500" size={28} />
            <p className="jb-body text-sm text-zinc-300">{estado === 'buscando' ? 'Buscando el producto…' : 'Leyendo la tabla nutricional…'}</p>
            {codigo && <p className="jb-body text-[11px] text-zinc-600 tabular-nums">Código {codigo}</p>}
          </div>
        )}

        {estado === 'producto' && producto && (
          <div>
            <div className="flex items-start gap-3 mb-4">
              <span className="w-11 h-11 rounded-full bg-orange-500/15 border border-orange-500/40 flex items-center justify-center text-xl shrink-0">📦</span>
              <div className="min-w-0">
                <p className="jb-display text-lg text-zinc-50 leading-tight">{producto.nombre}</p>
                <p className="jb-body text-xs text-zinc-500">
                  {producto.marca ? `${producto.marca} · ` : ''}{Math.round(producto.kcal)} kcal por 100 g
                  {Number(producto.porcion_g) > 0 ? ` · porción de ${Math.round(producto.porcion_g)} g` : ''}
                </p>
              </div>
            </div>
            {unidad === 'gramos' ? (
              // En gramos: regla (de 5 en 5 g) o tocar el número y escribirlo.
              <div className="mb-3 text-center">
                <input autoComplete="off" type="number" inputMode="decimal" min="1" step="any" value={cantidad} aria-label="Gramos"
                  onChange={e => setCantidad(e.target.value === '' ? 0 : Math.max(0, Number(e.target.value)))}
                  className="jb-display text-4xl text-zinc-50 tabular-nums leading-none bg-transparent text-center w-[140px] outline-none border-b-2 border-dashed border-zinc-700 focus:border-orange-500 pb-1" />
                <p className="jb-body text-sm text-zinc-400 mt-1">gramos</p>
                <ReglaDeslizable valor={cantidad || ''} onCambio={setCantidad} paso={5} min={5} max={1500} inicial={100} etiqueta="los gramos" />
              </div>
            ) : (
              <div className="flex items-center justify-center gap-5 mb-3">
                <BotonPaso grande etiqueta="Menos" onClick={() => setCantidad(c => Math.max(paso, Math.round((c - paso) * 10) / 10))}>−</BotonPaso>
                <div className="text-center min-w-[110px]">
                  <p className="jb-display text-4xl text-zinc-50 tabular-nums leading-none">{cantidad}</p>
                  <p className="jb-body text-sm text-zinc-400 mt-1">{cantidad === 1 ? 'porción' : 'porciones'}</p>
                </div>
                <BotonPaso grande etiqueta="Más" onClick={() => setCantidad(c => Math.round((c + paso) * 10) / 10)}>+</BotonPaso>
              </div>
            )}
            {Number(producto.porcion_g) > 0 && (
              <div className="flex justify-center gap-2 mb-4">
                {['porción', 'gramos'].map(u => (
                  <button key={u} type="button" onClick={() => { if (u === unidad) return; setUnidad(u); setCantidad(u === 'gramos' ? Math.max(10, Math.round(gramos / 10) * 10) : 1); }}
                    className={`jb-body text-xs px-3 py-1.5 rounded-full border transition-colors ${u === unidad ? 'bg-orange-500 border-orange-500 text-zinc-950 font-semibold' : 'border-zinc-700 text-zinc-300'}`}>
                    {u}
                  </button>
                ))}
              </div>
            )}
            <div className="bg-gradient-to-r from-orange-500/15 to-transparent border border-orange-500/40 rounded-xl px-4 py-3 mb-4 flex items-center justify-between gap-3">
              <p className="jb-body text-xs text-zinc-400 tabular-nums">
                {Math.round(gramos)} g · P {Math.round(macros.protein)}g · C {Math.round(macros.carbs)}g · G {Math.round(macros.fat)}g
              </p>
              <p className="jb-display text-3xl text-orange-500 tabular-nums leading-none">{Math.round(macros.kcal)}<span className="text-sm text-orange-400 ml-1">kcal</span></p>
            </div>
            <button onClick={agregar} disabled={!gramos} className={btnPrimary + ' w-full py-3'}>Agregar a {meal.toLowerCase()}</button>
            <p className="jb-body text-[11px] text-zinc-600 text-center mt-3">Datos de la etiqueta del producto.</p>
          </div>
        )}

        {estado === 'no_encontrado' && (
          <div>
            {codigo && (
              <p className="jb-body text-sm text-orange-400 font-semibold mb-2 flex items-center gap-1.5">
                <Check size={16} strokeWidth={3} /> Código leído: <span className="tabular-nums tracking-wider">{codigo}</span>
              </p>
            )}
            {mensaje
              ? <p className="jb-body text-sm text-amber-400 mb-2">{mensaje}</p>
              : <p className="jb-body text-sm text-zinc-200 mb-2">Este producto todavía no está registrado.</p>}
            {premium ? (
              <>
                <p className="jb-body text-sm text-zinc-400 mb-4">
                  <span className="text-zinc-100 font-semibold">Sé el primero en agregarlo:</span> tómale una foto a la <span className="text-orange-400 font-semibold">tabla nutricional</span> del empaque (de cerca y con buena luz). La leemos y queda guardado para ti y para todos los alumnos.
                </p>
                {botonFotoEtiqueta}
                <p className="jb-body text-[11px] text-zinc-600 text-center mt-2">Leer la etiqueta no usa tus fotos de comida.</p>
              </>
            ) : (
              <BloqueoPremium compacto titulo="Leer la etiqueta con foto es Premium"
                texto="Con Premium le tomas foto a la tabla nutricional y el producto queda guardado. Gratis puedes buscarlo por su nombre o crearlo tú." />
            )}
            <button onClick={onEscribir} className={btnGhost + ' w-full py-2.5 text-sm mt-3'}>Mejor lo busco por su nombre</button>
            {codigo && (
              <button type="button" onClick={() => { setMensaje(''); setEstado('camara'); }} className="w-full jb-body text-xs text-zinc-500 hover:text-zinc-300 mt-3 underline">Escanear de nuevo</button>
            )}
          </div>
        )}

        {estado === 'confirmar' && producto && (
          <div>
            <p className="jb-body text-sm text-zinc-200 mb-1 flex items-center gap-1.5"><Check size={16} strokeWidth={3} className="text-orange-400" /> Leímos la etiqueta.</p>
            <p className="jb-body text-xs text-zinc-500 mb-3">Revisa el nombre y toca <span className="text-orange-400 font-semibold">Guardar producto</span> para que quede registrado.</p>
            <label className="jb-body text-[11px] text-zinc-500">Nombre del producto
              <input autoComplete="off" value={nombreNuevo} onChange={e => setNombreNuevo(e.target.value.slice(0, 80))} placeholder="Ej. Yogurt bebible fresa" className={inputCls + ' w-full text-sm mt-0.5 mb-2'} />
            </label>
            <label className="jb-body text-[11px] text-zinc-500">Marca (opcional)
              <input autoComplete="off" value={marcaNueva} onChange={e => setMarcaNueva(e.target.value.slice(0, 40))} placeholder="Ej. Gloria" className={inputCls + ' w-full text-sm mt-0.5 mb-3'} />
            </label>
            <div className="bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2.5 mb-4 jb-body text-xs text-zinc-400 tabular-nums">
              Por 100 g: <span className="text-zinc-100 font-semibold">{Math.round(producto.kcal)} kcal</span> · P {producto.proteina} g · C {producto.carbos} g · G {producto.grasa} g
              {Number(producto.porcion_g) > 0 && <span className="block text-zinc-500 mt-0.5">Porción de la etiqueta: {Math.round(producto.porcion_g)} g</span>}
            </div>
            {mensaje && <p className="jb-body text-xs text-red-400 mb-2">{mensaje}</p>}
            <button onClick={guardarLeido} disabled={!nombreNuevo.trim() || guardando}
              className={btnPrimary + ' w-full py-3.5 mb-2 text-base shadow-[0_0_24px_rgba(232,89,12,.35)]'}>
              {guardando ? <Loader2 size={16} className="animate-spin" /> : <><Check size={18} strokeWidth={3} /> Guardar producto</>}
            </button>
            {!nombreNuevo.trim() && <p className="jb-body text-[11px] text-amber-400 text-center mb-2">Escribe el nombre del producto para guardarlo.</p>}
            <label className={btnGhost + ' w-full py-2.5 text-sm cursor-pointer'}>
              Los números no coinciden: otra foto
              <input type="file" accept="image/*" capture="environment" className="hidden" onChange={fotoEtiqueta} />
            </label>
          </div>
        )}

        {estado === 'limite' && (
          <div className="text-center py-2">
            <p className="jb-body text-sm text-zinc-300 mb-4">Ya leíste 5 etiquetas hoy. Mañana puedes leer más. Mientras tanto, puedes buscar el producto escribiendo.</p>
            <button onClick={onEscribir} className={btnPrimary + ' w-full py-2.5'}>Buscarlo escribiendo</button>
          </div>
        )}

        {estado === 'error' && (
          <div className="text-center py-2">
            <AlertTriangle className="text-amber-500 mx-auto mb-3" size={28} />
            <p className="jb-body text-sm text-zinc-400 mb-4">{mensaje || 'No se pudo buscar el producto. Intenta de nuevo.'}</p>
            <button onClick={() => (codigo ? buscar(codigo) : setEstado('camara'))} className={btnPrimary + ' w-full py-2.5 mb-2'}>Reintentar</button>
            <button onClick={onEscribir} className={btnGhost + ' w-full py-2.5 text-sm'}>Buscarlo escribiendo</button>
          </div>
        )}
      </div>
    </div>
  );
}

// Hoja que sube desde abajo al tocar "Registrar": elegir la comida (ya
// viene la que toca por la hora), y cómo registrar — foto, voz o escribir —
// más los atajos (repetir ayer, mis comidas, frecuentes).
/* ── REGISTRO ESCRITO (el que usa casi todo el mundo) ─────────────────────
   Una sola pantalla para anotar a mano, pensada para que sea fácil a
   cualquier edad:
   1. Arriba "Lo que comes siempre" en esta comida (sus 5 alimentos más
      frecuentes de los últimos 45 días): un toque y queda anotado con su
      cantidad de siempre.
   2. "¿Qué comiste?": al escribir, cada resultado dice cuánto es en una
      medida de casa ("1 plato ≈ 450 kcal"), no "por 100 g". Primero lo que
      suele comer y lo cocido; lo crudo va más abajo (salvo que escriba "crudo").
   3. Al elegir: "¿Cuánto comiste?" con botones grandes (½ plato, 1 plato…
      o 1, 2, 3 unidades), y si es frito o saltado, cuánto aceite tenía.
   4. Después de agregar: "¿Algo más en tu [comida]?" con la caja lista
      para el siguiente, y "Listo ✅" para terminar.
   Si no lo encuentra, "Buscarlo de otra forma" abre el buscador de siempre
   con lo que escribió (ahí puede pedírselo a Jonah o crearlo). */
const MULTIPLOS_MEDIDA = [0.5, 1, 1.5, 2];
const esCrudo = f => /crud/i.test(f?.state || '');
const fraccion = q => ({ 0.5: '½', 1.5: '1½', 2.5: '2½' }[q] || String(q));

function opcionesCantidad(food, unidad) {
  const d = unidadPorDefecto(food);
  const unit = unidad || d.unit;
  if (unit === 'gramos') {
    const base = d.unit === 'gramos' ? d.qty : 100;
    return MULTIPLOS_MEDIDA.map(m => ({ unit, qty: Math.max(5, Math.round((base * m) / 5) * 5) }));
  }
  if (UNIDADES_DISCRETAS.includes(unit)) return [1, 2, 3, 4].map(qty => ({ unit, qty }));
  return MULTIPLOS_MEDIDA.map(qty => ({ unit, qty }));
}
const textoCantidad = ({ unit, qty }) => {
  if (unit === 'gramos' || unit === 'ml' || UNIDADES_DISCRETAS.includes(unit)) return textoPorcion({ unit, qty });
  if (/[\s/]/.test(unit)) return qty === 1 ? `1 ${unit}` : `${fraccion(qty)} × ${unit}`;
  return `${fraccion(qty)} ${qty > 1 ? textoPorcion({ unit, qty: 2 }).replace(/^2 /, '') : unit}`;
};

function RegistroEscritoModal({ meal, username, todosLosAlimentos, mealPlan, setMealPlan, onOtraForma, onCerrar, onCambiarComida }) {
  const [texto, setTexto] = useState('');
  const [elegido, setElegido] = useState(null); // food
  const [unidad, setUnidad] = useState(null);
  const [aceite, setAceite] = useState('normal');
  const [otraMedida, setOtraMedida] = useState(false);
  // Cantidad exacta escrita a mano (para quien pesa su comida o sabe la medida).
  const [exacta, setExacta] = useState('');
  const [unidadExacta, setUnidadExacta] = useState('gramos');
  const [agregados, setAgregados] = useState([]); // [{ id, nombre, cantidad }]
  const [frecuentes, setFrecuentes] = useState([]); // [{ food, unit, qty }]
  const inputRef = useRef(null);

  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prev; };
  }, []);

  // Sus 5 alimentos más frecuentes en esta comida (con su cantidad más común).
  useEffect(() => {
    let vivo = true;
    if (!username) return undefined;
    supabase.from('historial').select('meal_plan').eq('username', username)
      .gte('fecha', addDaysISO(todayISO(), -45)).order('fecha', { ascending: false }).limit(60)
      .then(({ data }) => {
        if (!vivo) return;
        const conteo = {};
        (data || []).forEach(d => (d.meal_plan?.meals?.[meal] || []).forEach(en => {
          if (!en.foodKey) return;
          const c = conteo[en.foodKey] || (conteo[en.foodKey] = { n: 0, porciones: {} });
          c.n++;
          const p = porcionDeEntrada(en);
          const k = p.unit + '|' + p.qty;
          c.porciones[k] = (c.porciones[k] || 0) + 1;
        }));
        const lista = Object.entries(conteo).sort((a, b) => b[1].n - a[1].n).map(([key, c]) => {
          const food = buscarFood(key);
          if (!food) return null;
          const [unit, qty] = Object.entries(c.porciones).sort((a, b) => b[1] - a[1])[0][0].split('|');
          return { food, unit, qty: Number(qty), n: c.n };
        }).filter(Boolean).slice(0, 5);
        setFrecuentes(lista);
      }, () => {});
    return () => { vivo = false; };
  }, [username, meal]);

  const clavesFrecuentes = useMemo(() => new Set(frecuentes.map(f => f.food.key)), [frecuentes]);
  const resultados = useMemo(() => {
    if (!texto.trim()) return [];
    const quiereCrudo = /crud/i.test(texto);
    return buscarAlimentos(todosLosAlimentos, texto, 30)
      .map((f, i) => ({ f, i, p: (clavesFrecuentes.has(f.key) ? 0 : 2) + (!quiereCrudo && esCrudo(f) ? 1 : 0) }))
      .sort((a, b) => a.p - b.p || a.i - b.i)
      .slice(0, 12).map(x => x.f);
  }, [texto, todosLosAlimentos, clavesFrecuentes]);

  function agregar(food, porcion, aceiteElegido) {
    const entry = { id: uid(), foodKey: food.key, unit: porcion.unit, qty: porcion.qty };
    if (aceiteElegido && aceiteElegido !== 'normal' && preguntaAceite(food)?.opciones.some(o => o.key === aceiteElegido)) entry.aceite = aceiteElegido;
    setMealPlan(v => ({ ...v, meals: { ...v.meals, [meal]: [...(v.meals[meal] || []), entry] } }));
    vibrar(25);
    setAgregados(a => [...a, { id: entry.id, nombre: nombreAlimento(food), cantidad: textoCantidad(porcion) }]);
    setElegido(null); setUnidad(null); setAceite('normal'); setOtraMedida(false); setTexto(''); setExacta('');
    setTimeout(() => inputRef.current?.focus(), 50);
  }
  function quitar(id) {
    setMealPlan(v => ({ ...v, meals: { ...v.meals, [meal]: (v.meals[meal] || []).filter(e => e.id !== id) } }));
    setAgregados(a => a.filter(x => x.id !== id));
  }
  const kcalDe = (food, porcion, ac) => Math.round(entryMacros({ foodKey: food.key, unit: porcion.unit, qty: porcion.qty, aceite: ac && ac !== 'normal' ? ac : undefined }).kcal);

  return (
    <div className="fixed inset-0 z-50 flex flex-col justify-end">
      <div className="jbm-fondo absolute inset-0 bg-black/75" onClick={onCerrar} />
      <div className="jbm-hoja relative bg-zinc-900 border-t border-orange-500/50 rounded-t-3xl h-[92vh] overflow-y-auto px-5 pt-3"
        style={{ paddingBottom: 'max(1.25rem, env(safe-area-inset-bottom))' }}>
        <div className="w-10 h-1 rounded-full bg-zinc-700 mx-auto mb-3" />
        <div className="flex items-center justify-between mb-3 gap-2">
          <h3 className="jb-display text-xl text-zinc-50 tracking-wide">{ICONO_COMIDA[meal]} {meal.toUpperCase()}</h3>
          <button onClick={onCerrar} className={btnPrimary + ' px-4 py-2 text-sm shrink-0'}>{agregados.length ? 'Listo ✅' : 'Cerrar'}</button>
        </div>
        {/* La comida se puede cambiar aquí mismo (ej. un almuerzo tarde,
            después de las 3:30). Una vez que anotó algo, queda fija. */}
        {onCambiarComida && !agregados.length && (
          <SelectorComida valor={meal} onCambio={onCambiarComida} ahora={comidaDeAhora()} className="mb-3 -mx-5 px-5" />
        )}

        {agregados.length > 0 && (
          <div className="bg-zinc-950 border border-zinc-800 rounded-2xl p-3 mb-3">
            <p className="jb-body text-xs text-zinc-500 mb-1.5">Ya anotaste:</p>
            {agregados.map(a => (
              <div key={a.id} className="flex items-center gap-2 py-1">
                <span className="text-emerald-400">✓</span>
                <span className="jb-body text-sm text-zinc-100 flex-1 min-w-0">{a.nombre} <span className="text-zinc-500">· {a.cantidad}</span></span>
                <button onClick={() => quitar(a.id)} className="jb-body text-xs text-zinc-500 underline shrink-0">Quitar</button>
              </div>
            ))}
          </div>
        )}

        {elegido ? (
          <div className="flex flex-col gap-3">
            <button onClick={() => setElegido(null)} className="jb-body text-sm text-zinc-400 self-start">← Elegir otro</button>
            <div>
              <p className="jb-display text-2xl text-zinc-50 leading-tight">{nombreAlimento(elegido).toUpperCase()}</p>
              <NotaSinArroz food={elegido} className="!text-sm mt-1" />
              <p className="jb-body text-base text-zinc-400 mt-1">¿Cuánto comiste?</p>
            </div>
            <div className="grid grid-cols-2 gap-2">
              {opcionesCantidad(elegido, unidad).map(op => (
                <button key={op.unit + op.qty} onClick={() => agregar(elegido, op, aceite)}
                  className="rounded-2xl border border-zinc-700 bg-zinc-950 hover:border-orange-500 px-3 py-4 text-center">
                  <span className="jb-display text-xl text-zinc-50 block">{textoCantidad(op)}</span>
                  <span className="jb-body text-sm text-orange-400 block mt-0.5">≈ {kcalDe(elegido, op, aceite)} kcal</span>
                </button>
              ))}
            </div>
            {(() => {
              // "¿Sabes la cantidad exacta?": un número y su medida (gramos por defecto).
              const qty = Number(String(exacta).replace(',', '.'));
              const gramos = qty * (unidadExacta === 'gramos' ? 1 : (unitsFor(elegido).find(u => u[0] === unidadExacta)?.[1] || 1));
              const valida = qty > 0 && gramos <= 5000;
              const porcion = { unit: unidadExacta, qty: Math.round(qty * 100) / 100 };
              return (
                <form className="rounded-2xl border border-zinc-800 bg-zinc-950 p-3" onSubmit={e => { e.preventDefault(); if (valida) agregar(elegido, porcion, aceite); }}>
                  <p className="jb-body text-sm text-zinc-300 mb-2">✏️ ¿Sabes la cantidad exacta? Escríbela:</p>
                  <div className="flex items-center gap-2">
                    <input autoComplete="off" type="number" inputMode="decimal" min="0" step="any" value={exacta} onChange={e => setExacta(e.target.value)}
                      placeholder="Ej. 120" aria-label="Cantidad exacta"
                      className="flex-1 min-w-0 jb-body text-lg rounded-xl px-3 py-2 bg-zinc-900 border border-zinc-700 focus:border-orange-500 text-zinc-50 outline-none tabular-nums" />
                    <button type="submit" disabled={!valida} className={btnPrimary + ' px-4 py-2.5 text-sm shrink-0 disabled:opacity-40'}>Agregar</button>
                  </div>
                  {/* La medida, con botoncitos (igual que en "Editar a fondo"). */}
                  <div className="flex flex-wrap gap-1.5 mt-2" role="group" aria-label="Medida">
                    {unitsFor(elegido).map(([u]) => (
                      <button key={u} type="button" onClick={() => { vibrar(8); setUnidadExacta(u); }} aria-pressed={unidadExacta === u}
                        className={`jb-body text-sm px-3 py-1.5 rounded-full border ${unidadExacta === u ? 'bg-orange-500 border-orange-500 text-zinc-950 font-semibold' : 'border-zinc-700 text-zinc-300'}`}>
                        {u}
                      </button>
                    ))}
                  </div>
                  {valida && <p className="jb-body text-xs text-orange-400 mt-1.5">≈ {kcalDe(elegido, porcion, aceite)} kcal</p>}
                  {qty > 0 && !valida && <p className="jb-body text-xs text-amber-400 mt-1.5">Cantidad muy alta, revísala.</p>}
                </form>
              );
            })()}
            {preguntaAceite(elegido) && (
              <div>
                <p className="jb-body text-sm text-zinc-300 mb-1.5">{preguntaAceite(elegido).titulo}</p>
                <div className="flex flex-wrap gap-1.5">
                  {preguntaAceite(elegido).opciones.map(o => (
                    <button key={o.key} onClick={() => setAceite(o.key)}
                      className={`jb-body text-sm px-3 py-2 rounded-full border ${aceite === o.key ? 'bg-orange-500 border-orange-500 text-zinc-950 font-semibold' : 'border-zinc-700 text-zinc-300'}`}>
                      {o.label}
                    </button>
                  ))}
                </div>
              </div>
            )}
            {unitsFor(elegido).length > 1 && (
              <div>
                <button onClick={() => setOtraMedida(v => !v)} className="jb-body text-sm text-zinc-400 underline">
                  {otraMedida ? 'Ocultar medidas' : 'Usar otra medida (taza, gramos…)'}
                </button>
                {otraMedida && (
                  <div className="flex flex-wrap gap-1.5 mt-2">
                    {unitsFor(elegido).map(([u]) => (
                      <button key={u} onClick={() => setUnidad(u)}
                        className={`jb-body text-sm px-3 py-2 rounded-full border ${(unidad || unidadPorDefecto(elegido).unit) === u ? 'bg-orange-500 border-orange-500 text-zinc-950 font-semibold' : 'border-zinc-700 text-zinc-300'}`}>
                        {u}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        ) : (
          <div className="flex flex-col gap-3">
            <label className="jb-display text-lg text-zinc-50" htmlFor="jb-que-comiste">
              {agregados.length ? `¿ALGO MÁS EN TU ${meal.toUpperCase()}?` : '¿QUÉ COMISTE?'}
            </label>
            <input autoComplete="off" id="jb-que-comiste" ref={inputRef} autoFocus value={texto} onChange={e => setTexto(e.target.value)}
              placeholder="Escríbelo aquí: arroz, pollo, pan…"
              className="w-full jb-body text-lg rounded-2xl px-4 py-3.5 bg-zinc-950 border-2 border-orange-500/60 text-zinc-50 focus:outline-none focus:border-orange-500" />

            {!texto.trim() && frecuentes.length > 0 && (
              <div>
                <p className="jb-body text-sm text-zinc-400 mb-1.5">⭐ Lo que comes siempre en tu {meal.toLowerCase()} (un toque y listo):</p>
                <div className="flex flex-col gap-1.5">
                  {frecuentes.map(fr => (
                    <button key={fr.food.key} onClick={() => agregar(fr.food, { unit: fr.unit, qty: fr.qty })}
                      className="w-full flex items-center gap-3 text-left rounded-xl bg-zinc-950 border border-zinc-800 hover:border-orange-500 px-3 py-3">
                      <span className="text-xl shrink-0">{emojiAlimento(fr.food)}</span>
                      <span className="min-w-0 flex-1">
                        <span className="jb-body text-base text-zinc-100 block leading-snug">{nombreAlimento(fr.food)}</span>
                        <NotaSinArroz food={fr.food} />
                        <span className="jb-body text-sm text-zinc-500 block">{textoCantidad({ unit: fr.unit, qty: fr.qty })} · ≈ {kcalDe(fr.food, fr)} kcal</span>
                      </span>
                      <span className="jb-display text-orange-400 text-xl shrink-0">+</span>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {texto.trim() && (
              <div className="flex flex-col gap-1.5">
                {resultados.map(f => {
                  const d = unidadPorDefecto(f);
                  return (
                    <button key={f.key} onClick={() => { setElegido(f); setUnidad(null); setAceite('normal'); setOtraMedida(false); setExacta(''); setUnidadExacta(unitsFor(f).some(u => u[0] === 'gramos') ? 'gramos' : unidadPorDefecto(f).unit); }}
                      className="w-full flex items-center gap-3 text-left rounded-xl bg-zinc-950 border border-zinc-800 hover:border-orange-500 px-3 py-3">
                      <span className="text-xl shrink-0">{emojiAlimento(f)}</span>
                      <span className="min-w-0 flex-1">
                        <span className="jb-body text-base text-zinc-100 block leading-snug">{nombreAlimento(f)}{clavesFrecuentes.has(f.key) ? ' ⭐' : ''}</span>
                        <NotaSinArroz food={f} />
                        <span className="jb-body text-sm text-zinc-500 block">{textoCantidad(d)} ≈ {kcalDe(f, d)} kcal{f.esPersonal ? ' · tuyo' : ''}</span>
                      </span>
                      <ChevronRight size={18} className="text-zinc-600 shrink-0" />
                    </button>
                  );
                })}
                <button onClick={() => onOtraForma(texto.trim())}
                  className="w-full rounded-xl border border-dashed border-zinc-700 px-3 py-3 jb-body text-sm text-orange-400 text-left">
                  {resultados.length ? '¿No es ninguno?' : `No encontramos "${texto.trim()}".`} Buscarlo de otra forma, pedírselo a Jonah o crearlo →
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

/* 💧 AGUA: vasos de 250 ml del día, un toque por vaso. La meta sale del
   peso (unos 35 ml por kilo, entre 6 y 14 vasos). Se guarda con las
   comidas del día (mealPlan.agua), así queda en el historial de ese día. */
function metaAgua(peso) {
  const n = Math.round(((Number(peso) || 70) * 35) / 250);
  return Math.min(14, Math.max(6, n));
}
function AguaFila({ mealPlan, setMealPlan, peso }) {
  const meta = metaAgua(peso);
  const vasos = Math.max(0, Number(mealPlan?.agua) || 0);
  function fijar(n) {
    const nuevo = Math.max(0, Math.min(30, n));
    vibrar(nuevo > vasos ? 12 : 8);
    setMealPlan(v => ({ ...v, agua: nuevo }));
    if (nuevo === meta && vasos < meta) showToast('💧 ¡Meta de agua cumplida! Tu cuerpo te lo agradece.');
  }
  return (
    <div className="bg-zinc-900 border border-zinc-800 rounded-2xl px-4 py-3 mb-4">
      <div className="flex items-center justify-between mb-2">
        <span className="jb-display text-sm text-zinc-200 tracking-wide">💧 AGUA</span>
        <span className={`jb-body text-xs tabular-nums ${vasos >= meta ? 'text-emerald-400 font-semibold' : 'text-zinc-400'}`}>
          {vasos}/{meta} vasos · {(vasos * 0.25).toFixed(vasos % 4 ? 2 : 1).replace(/\.?0+$/, '')} L{vasos >= meta ? ' ✓' : ''}
        </span>
      </div>
      <div className="flex items-center gap-1 flex-wrap">
        {Array.from({ length: Math.max(meta, vasos) }, (_, i) => {
          const lleno = i < vasos;
          return (
            <button key={i} type="button" onClick={() => fijar(lleno && i === vasos - 1 ? i : i + 1)}
              aria-label={lleno ? `Vaso ${i + 1} (tomado)` : `Tomé el vaso ${i + 1}`}
              className={`w-8 h-9 rounded-lg flex items-center justify-center text-base border transition-colors ${lleno ? 'bg-sky-500/20 border-sky-400/60' : 'bg-zinc-950 border-zinc-800 opacity-50'}`}>
              💧
            </button>
          );
        })}
        <button type="button" onClick={() => fijar(vasos + 1)} aria-label="Un vaso más"
          className="ml-auto jb-body text-xs font-semibold text-sky-300 border border-sky-500/50 rounded-full px-3 py-2">+ 1 vaso</button>
      </div>
    </div>
  );
}

/* Selector de comida (Desayuno, Media mañana…): el mismo en toda la app
   (Registrar, Restaurantes aliados, "¿Qué puedo comer?"…). Naranja el
   elegido; el puntito marca la comida de la hora. */
function SelectorComida({ valor, onCambio, ahora = null, className = '' }) {
  return (
    <div className={'flex gap-2 overflow-x-auto pb-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden ' + className} role="group" aria-label="Comida">
      {MEAL_NAMES.map(m => (
        <button key={m} type="button" onClick={() => { vibrar(8); onCambio(m); }} aria-pressed={valor === m}
          className={`jb-body text-xs px-3 py-2 min-h-[36px] rounded-full flex items-center gap-1.5 shrink-0 border transition-colors ${valor === m
            ? 'bg-orange-500 border-orange-500 text-zinc-950 font-semibold'
            : 'bg-zinc-950 border-zinc-800 text-zinc-400'}`}>
          <span>{ICONO_COMIDA[m] || '🍴'}</span>{m}
          {m === ahora && <span className={`w-1.5 h-1.5 rounded-full ${valor === m ? 'bg-zinc-950' : 'bg-orange-500'}`} title="Ahora" />}
        </button>
      ))}
    </div>
  );
}

function HojaRegistrar({ meal, setMeal, onCerrar, onFoto, onCodigo, onEscribir, onBuscarDespues, onAgregado, username, mealPlan, setMealPlan }) {
  const [modo, setModo] = useState(null); // null | 'voz'
  const { premium } = usePremium();
  const ahora = comidaDeAhora();

  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prev; };
  }, []);

  const opciones = [
    { id: 'foto', icono: <Camera size={20} />, titulo: 'Foto', sub: 'La IA lo reconoce', accion: () => onFoto(meal) },
    { id: 'codigo', icono: <ScanBarcode size={20} />, titulo: 'Código', sub: 'Productos empacados', accion: () => onCodigo(meal) },
    { id: 'voz', icono: <Mic size={20} />, titulo: 'Voz', sub: premium ? 'Dile a Jonah' : '👑 Premium', accion: () => setModo(m => m === 'voz' ? null : 'voz') },
  ];

  return (
    <div className="fixed inset-0 z-50 flex flex-col justify-end">
      <div className="jbm-fondo absolute inset-0 bg-black/75" onClick={onCerrar} />
      <div className="jbm-hoja relative bg-zinc-900 border-t border-orange-500/50 rounded-t-3xl max-h-[88vh] overflow-y-auto px-5 pt-3"
        style={{ paddingBottom: 'max(1.25rem, env(safe-area-inset-bottom))', boxShadow: '0 -12px 40px rgba(232,89,12,.18)' }}>
        <div className="w-10 h-1 rounded-full bg-zinc-700 mx-auto mb-4" />
        <div className="flex items-center justify-between mb-3">
          <h3 className="jb-display text-lg text-zinc-50 tracking-wide">REGISTRAR</h3>
          <button onClick={onCerrar} className="text-zinc-500 hover:text-zinc-300 p-2.5 -m-1.5" aria-label="Cerrar"><X size={18} /></button>
        </div>

        <SelectorComida valor={meal} onCambio={setMeal} ahora={ahora} className="mb-4 -mx-5 px-5" />

        {/* Escribir es como registra casi todo el mundo: va primero y grande. */}
        <button onClick={() => onEscribir(meal)}
          className="w-full flex items-center gap-3 rounded-2xl border-2 border-orange-500/60 bg-zinc-950 px-4 py-4 mb-3 text-left hover:border-orange-500">
          <span className="w-11 h-11 rounded-full bg-orange-500 text-zinc-950 flex items-center justify-center shrink-0 jb-display text-lg">✍️</span>
          <span className="min-w-0">
            <span className="jb-display text-lg text-zinc-50 block leading-tight">¿QUÉ COMISTE? ESCRÍBELO AQUÍ</span>
            <span className="jb-body text-xs text-zinc-400 block">Arroz, pollo, pan… y eliges cuánto. También lo que comes siempre.</span>
          </span>
        </button>
        <div className="grid grid-cols-3 gap-2 mb-4">
          {opciones.map(o => {
            const activo = o.id === 'voz' && modo === 'voz';
            return (
              <button key={o.id} onClick={o.accion}
                className={`rounded-2xl border px-1 py-3.5 flex flex-col items-center gap-1.5 transition-colors ${activo
                  ? 'bg-orange-500 border-orange-500 text-zinc-950'
                  : 'bg-zinc-950 border-orange-500/40 text-orange-400 hover:bg-orange-500/10'}`}
                style={activo ? undefined : { boxShadow: 'inset 0 0 18px rgba(232,89,12,.12)' }}>
                <span className={`w-11 h-11 rounded-full flex items-center justify-center ${activo ? 'bg-zinc-950/15' : 'bg-orange-500/15 border border-orange-500/40'}`}>{o.icono}</span>
                <span className={`jb-display text-sm ${activo ? 'text-zinc-950' : 'text-zinc-100'}`}>{o.titulo}</span>
                <span className={`jb-body text-[10px] leading-tight text-center ${activo ? 'text-zinc-900' : 'text-zinc-500'}`}>{o.sub}</span>
              </button>
            );
          })}
        </div>

        {modo === 'voz' && !premium && (
          <div className="mb-4"><ModoVoz /></div>
        )}
        {modo === 'voz' && premium && (
          <div className="bg-zinc-950 border border-zinc-800 rounded-2xl p-4 mb-4">
            <RegistroRapido username={username} mealPlan={mealPlan} setMealPlan={setMealPlan}
              restricciones={mealPlan.restricciones || []} embebido meal={meal}
              onBuscarDespues={onBuscarDespues ? textos => onBuscarDespues(meal, textos) : undefined}
              onAgregado={onAgregado} />
          </div>
        )}

        {username && (
          <div>
            <p className="jb-body text-[11px] text-zinc-500 uppercase tracking-wider mb-2">Atajos para {meal.toLowerCase()}</p>
            <AtajosComida username={username} meal={meal} mealPlan={mealPlan} setMealPlan={setMealPlan} onAgregado={onAgregado} />
          </div>
        )}
      </div>
    </div>
  );
}

// Guisos que en Perú se comen con arroz pero cuyas calorías NO lo incluyen:
// se avisa "Sin arroz: agrégalo aparte" para que no se olvide de anotarlo.
// Los de la lista fija (RAW_FOODS) van aquí; los agregados desde el panel o
// por la IA traen la casilla "sin_arroz" de alimentos_extra (food.sinArroz).
// Los que ya traen el arroz en el nombre ("Arroz con pollo", "Pollo a la
// olla con arroz") no van.
const PLATOS_SIN_ARROZ = new Set([
  'Ají de gallina', 'Ají de pollo', 'Pollo al sillao', 'Estofado de pollo',
  'Escabeche de pollo', 'Estofado de carne', 'Seco de res con frejoles', 'Lomo saltado',
  'Adobo de cerdo', 'Carapulcra', 'Olluquito con charqui', 'Cau cau', 'Chanfainita',
  'Sudado de pescado',
]);
const esPlatoSinArroz = food => !!food && (!!food.sinArroz || (!food.esExtra && PLATOS_SIN_ARROZ.has(food.name)));
function NotaSinArroz({ food, className = '' }) {
  if (!esPlatoSinArroz(food)) return null;
  return <span className={'block jb-body text-[11px] text-amber-300/90 leading-snug ' + className}>🍚 Sin arroz: agrégalo aparte</span>;
}

// Nombre para mostrar: "Huevo de gallina · cocido" en vez de "Huevo de gallina (Cocido)".
function nombreAlimento(food) {
  if (!food) return '';
  return food.state && food.state !== '-' ? `${food.name} · ${food.state.toLowerCase()}` : food.name;
}

// Unidad y cantidad actuales de una entrada (las antiguas guardaban solo gramos).
function porcionDeEntrada(en) {
  const sinUnidad = en.unit === undefined || en.unit === null;
  return { unit: sinUnidad ? 'gramos' : en.unit, qty: Number(sinUnidad ? en.grams : en.qty) || 0 };
}

function BotonPaso({ onClick, children, grande = false, etiqueta }) {
  return (
    <button type="button" onClick={e => { e.stopPropagation(); vibrar(8); onClick(); }} aria-label={etiqueta}
      className={`${grande ? 'w-12 h-12 text-2xl' : 'w-8 h-8 text-base'} relative after:absolute after:-inset-1.5 after:content-[''] rounded-full bg-zinc-900 border border-orange-500/40 text-orange-400 hover:bg-orange-500/15 active:scale-95 flex items-center justify-center shrink-0 transition-transform jb-display leading-none`}>
      {children}
    </button>
  );
}

/* "🧩 Ajustar ingredientes": cambia un plato registrado por sus partes
   (src/recetasPlatos.js), escaladas a lo que registró (1 unidad, 2
   unidades, 300 g…). Devuelve null si el plato no tiene receta. */
function partesDelPlato(en) {
  const receta = RECETAS_PLATOS[en.foodKey];
  const plato = buscarFood(en.foodKey);
  if (!receta || !plato) return null;
  const medida = unitsFor(plato).find(([u]) => u !== 'gramos');
  const gramosPorcion = medida ? medida[1] : 100;
  const factor = entryGrams(en) / gramosPorcion || 1;
  const partes = receta.map(([foodKey, qty, unit]) => {
    const food = buscarFood(foodKey);
    if (!food) return null;
    let q = qty * factor;
    if (unit === 'gramos') q = Math.max(5, Math.round(q / 5) * 5);
    else if (UNIDADES_DISCRETAS.includes(unit)) q = Math.max(1, Math.round(q));
    else q = Math.max(0.5, Math.round(q * 2) / 2);
    return { id: uid(), foodKey, unit, qty: q };
  }).filter(Boolean);
  return partes.length ? partes : null;
}

/* Recibir su plan por WhatsApp: antes estaba en la pantalla del plan, pero
   sacaba a la gente antes de crear su cuenta. Ahora sale en Inicio recién
   cuando ya registró su primera comida (en su prueba), una sola vez: al
   tocarlo o con "Ahora no" no vuelve a salir. Dentro de TikTok/Instagram no
   sale, porque abrir WhatsApp ahí cierra la app. */
function PlanPorWhatsApp({ username, form, kcal, proteina }) {
  const clave = 'jb_plan_wa_' + username;
  const [visible, setVisible] = useState(() => {
    try { return !localStorage.getItem(clave) && !equipoDelAlumno().navegadorInterno; } catch { return false; }
  });
  if (!visible || !form?.objetivo || !kcal) return null;
  const cerrar = () => { setVisible(false); try { localStorage.setItem(clave, '1'); } catch {} };
  const texto = mensajePlanWhatsApp(
    { objetivo: form.objetivo, peso: form.peso, pesoObjetivo: form.pesoObjetivo },
    { kcal: Math.round(kcal / 10) * 10, proteina: Math.round(proteina || 0), semanas: null },
    'Ya registré mi primera comida en la app. ¿Me ayudas a seguir?');
  return (
    <div className="bg-zinc-900 border border-orange-500/40 rounded-2xl p-4 mb-4">
      <p className="jb-display text-base text-zinc-50">📲 ¿TE MANDO TU PLAN POR WHATSAPP?</p>
      <p className="jb-body text-sm text-zinc-400 mt-1">Ya registraste tu primera comida 💪. Escríbeme con tu plan y te acompaño también por WhatsApp.</p>
      <div className="flex gap-2 mt-3">
        <a href={`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(texto)}`} target="_blank" rel="noopener noreferrer"
          onClick={cerrar} className={btnPrimary + ' flex-1 py-2.5 text-sm'}>Recibir mi plan por WhatsApp</a>
        <button type="button" onClick={cerrar} className={btnGhost + ' py-2.5 text-sm'}>Ahora no</button>
      </div>
    </div>
  );
}

/* Recién registrado desde el navegador de TikTok, Instagram o Facebook
   (así llega casi todo el que viene de un anuncio): ahí no le llegan los
   avisos ni puede instalar la app. Se le pide, con cariño y una sola vez
   al día, abrirla en Chrome o Safari. Su cuenta ya está guardada: solo
   entra con su correo. */
function AbrirEnNavegadorModal({ username, onCerrar }) {
  const { dispositivo, app } = equipoDelAlumno();
  useEffect(() => { registrarPasoPago('abrir_navegador', username, 'vio'); }, [username]);
  const [correo, setCorreo] = useState('');
  const [copiado, setCopiado] = useState(false);
  const [correoCopiado, setCorreoCopiado] = useState(false);
  const [conGoogle, setConGoogle] = useState(false);
  useEffect(() => {
    supabase.auth.getUser().then(({ data }) => {
      setCorreo(data?.user?.email || '');
      setConGoogle((data?.user?.app_metadata?.providers || [data?.user?.app_metadata?.provider]).includes('google'));
    }, () => {});
  }, []);
  async function copiarCorreo() {
    try { await navigator.clipboard.writeText(correo); setCorreoCopiado(true); } catch {}
  }
  const esIphone = dispositivo === 'iphone';
  const navegador = esIphone ? 'Safari' : 'Chrome';
  // Android: abre Chrome directo. iPhone (iOS 17+): abre Safari directo.
  const enlace = esIphone
    ? 'x-safari-https://jonahbeast.com/?desde=app'
    : 'intent://jonahbeast.com/?desde=app#Intent;scheme=https;package=com.android.chrome;end';
  async function copiar() {
    try { await navigator.clipboard.writeText('https://jonahbeast.com'); setCopiado(true); } catch {}
  }
  return (
    <div className="fixed inset-0 bg-black/80 flex items-end sm:items-center justify-center sm:p-4 z-50">
      <div className="max-h-[90vh] overflow-y-auto pb-[max(1.5rem,env(safe-area-inset-bottom))] sm:pb-6 bg-zinc-900 border border-orange-500/40 rounded-t-3xl sm:rounded-2xl max-w-md w-full p-6 text-center">
        <AsaHoja />
        <div className="w-16 h-16 rounded-full bg-orange-500/15 border border-orange-500/30 flex items-center justify-center text-4xl mx-auto mb-3">🦍</div>
        <h2 className="jb-display text-xl text-zinc-50 mb-3">UN ÚLTIMO PASO PARA ACOMPAÑARTE</h2>
        <p className="jb-body text-sm text-zinc-300 leading-relaxed">
          Estás usando la app dentro de {app === 'otra app' ? 'otra app' : app}. Ahí <b className="text-zinc-100">no te llegan mis avisos</b> ni puedes instalarla.
          Ábrela en <b className="text-zinc-100">{navegador}</b>: tu cuenta y tu plan ya están guardados.
        </p>
        {correo && (
          <div className="mt-4 bg-zinc-950 border border-orange-500/30 rounded-xl p-3">
            <p className="jb-body text-[11px] text-zinc-400 uppercase tracking-wider">{conGoogle ? 'Allá toca "Continuar con Google" con' : 'Allá entras con tu correo'}</p>
            <p className="jb-body text-base text-orange-400 font-semibold break-all mt-0.5">{correo}</p>
            <button type="button" onClick={copiarCorreo} className="jb-body text-[11px] text-orange-400 underline mt-1">
              {correoCopiado ? '✅ Correo copiado' : 'Copiar mi correo'}
            </button>
            {!conGoogle && (
              <p className="jb-body text-[11px] text-zinc-500 mt-1.5">¿No recuerdas tu contraseña? Allá toca <b className="text-zinc-300">"¿Olvidaste tu contraseña?"</b> y te llega un enlace a este correo.</p>
            )}
          </div>
        )}
        <a href={enlace} onClick={() => registrarPasoPago('abrir_navegador', username, 'toco')} className={btnPrimary + ' w-full py-3 mt-4'}>🌐 Abrir en {navegador}</a>
        <div className="mt-3 bg-zinc-950 border border-zinc-800 rounded-lg p-2.5 text-left">
          <p className="jb-body text-[11px] text-zinc-400">
            Si no se abre: toca los <b className="text-zinc-200">tres puntos</b> (arriba a la derecha) → <b className="text-zinc-200">"Abrir en {esIphone ? 'Safari' : 'el navegador'}"</b>. O escribe <b className="text-zinc-200">jonahbeast.com</b> en {navegador}.
          </p>
          <button type="button" onClick={copiar} className="jb-body text-[11px] text-orange-400 underline mt-1.5">
            {copiado ? '✅ Enlace copiado' : 'Copiar el enlace'}
          </button>
        </div>
        <button type="button" onClick={onCerrar} className="jb-body text-sm text-zinc-400 hover:text-zinc-200 underline underline-offset-2 mt-4">
          Seguir aquí por ahora
        </button>
      </div>
    </div>
  );
}

// Panel que sube al tocar un alimento: cantidad con − / + grandes, medida
// en botones, macros, cambiar de alimento, reemplazo equivalente y borrar.
function HojaEditarAlimento({ meal, en, todosLosAlimentos, username, mealPlan, updateEntry, removeEntry, onCrear, onEditarPropio, onDesarmar, onCerrar }) {
  const [verSustitutos, setVerSustitutos] = useState(false);
  // El número grande también se escribe a mano (ej. 37 g), no solo con − / +.
  const [escribiendo, setEscribiendo] = useState(null); // texto mientras escribe
  const food = buscarFood(en.foodKey);

  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prev; };
  }, []);

  if (!food) return null;
  const porcion = porcionDeEntrada(en);
  const m = entryMacros(en);
  const unidades = unitsFor(food);
  const bucket = grupoDeSustitucion(food);

  const fijar = (patch) => updateEntry(meal, en.id, { ...patch, grams: undefined });
  function guardarEscrito() {
    const n = Number(String(escribiendo ?? '').replace(',', '.'));
    if (n > 0 && n * (porcion.unit === 'gramos' ? 1 : (unidades.find(u => u[0] === porcion.unit)?.[1] || 1)) <= 5000) {
      fijar({ unit: porcion.unit, qty: Math.round(n * 100) / 100 });
    }
    setEscribiendo(null);
  }

  return (
    <div className="fixed inset-0 z-50 flex flex-col justify-end">
      <div className="jbm-fondo absolute inset-0 bg-black/75" onClick={onCerrar} />
      <div className="jbm-hoja relative bg-zinc-900 border-t border-orange-500/50 rounded-t-3xl max-h-[88vh] overflow-y-auto px-5 pt-3"
        style={{ paddingBottom: 'max(1.25rem, env(safe-area-inset-bottom))', boxShadow: '0 -12px 40px rgba(232,89,12,.18)' }}>
        <div className="w-10 h-1 rounded-full bg-zinc-700 mx-auto mb-4" />
        <div className="flex items-start gap-3 mb-5">
          <span className="w-11 h-11 rounded-full bg-orange-500/15 border border-orange-500/40 flex items-center justify-center text-xl shrink-0">{emojiAlimento(food)}</span>
          <div className="flex-1 min-w-0">
            <p className="jb-display text-lg text-zinc-50 leading-tight">{nombreAlimento(food)}</p>
            <NotaSinArroz food={food} />
            <p className="jb-body text-xs text-zinc-500">{meal}</p>
          </div>
          <button onClick={onCerrar} className="text-zinc-500 hover:text-zinc-300 p-2.5 -m-1.5" aria-label="Cerrar"><X size={18} /></button>
        </div>

        {/* En gramos se elige con la regla (de 5 en 5 g) o escribiéndolo; en
            unidades, tazas, platos… con − y +. */}
        <div className="flex items-center justify-center gap-5 mb-3">
          {porcion.unit !== 'gramos' && <BotonPaso grande etiqueta="Menos" onClick={() => {
            const nueva = cambiarCantidad(porcion.qty, porcion.unit, -1);
            // En lo mínimo, "−" lo quita (cero).
            if (nueva >= Number(porcion.qty)) { removeEntry(meal, en.id); onCerrar(); return; }
            fijar({ unit: porcion.unit, qty: nueva });
          }}>−</BotonPaso>}
          <div className="text-center min-w-[120px]">
            <input autoComplete="off" type="number" inputMode="decimal" min="0" step="any" aria-label="Cantidad (toca para escribirla)"
              value={escribiendo ?? porcion.qty}
              onFocus={e => { setEscribiendo(String(porcion.qty)); e.target.select(); }}
              onChange={e => setEscribiendo(e.target.value)}
              onBlur={guardarEscrito}
              onKeyDown={e => { if (e.key === 'Enter') e.currentTarget.blur(); }}
              className="jb-display text-4xl text-zinc-50 tabular-nums leading-none bg-transparent text-center w-[120px] outline-none border-b-2 border-dashed border-zinc-700 focus:border-orange-500 pb-1" />
            <p className="jb-body text-sm text-zinc-400 mt-1">{porcion.unit === 'gramos' ? 'gramos' : textoPorcion(porcion).replace(/^\S+\s/, '')}</p>
          </div>
          {porcion.unit !== 'gramos' && <BotonPaso grande etiqueta="Más" onClick={() => fijar({ unit: porcion.unit, qty: cambiarCantidad(porcion.qty, porcion.unit, 1) })}>+</BotonPaso>}
        </div>
        {porcion.unit === 'gramos' && (
          <div className="mb-3">
            <ReglaDeslizable valor={Number(porcion.qty) || ''} paso={5} min={5} max={1500} inicial={100} etiqueta="los gramos"
              onCambio={g => fijar({ unit: 'gramos', qty: g })} />
          </div>
        )}

        {unidades.length > 1 && (
          <div className="flex flex-wrap justify-center gap-2 mb-4">
            {unidades.map(([u]) => (
              <button key={u} type="button"
                onClick={() => {
                  if (u === porcion.unit) return;
                  const d = u === 'gramos' ? { qty: Math.max(10, Math.round(entryGrams(en) / 10) * 10) } : { qty: 1 };
                  fijar({ unit: u, qty: d.qty });
                }}
                className={`jb-body text-xs px-3 py-1.5 rounded-full border transition-colors ${u === porcion.unit ? 'bg-orange-500 border-orange-500 text-zinc-950 font-semibold' : 'border-zinc-700 text-zinc-300'}`}>
                {u}
              </button>
            ))}
          </div>
        )}

        <div className="bg-zinc-950 border border-orange-500/30 rounded-2xl px-4 py-3 mb-4 flex items-center justify-between">
          <p className="jb-display text-2xl text-orange-500 tabular-nums">{Math.round(m.kcal)} <span className="text-sm text-orange-400">kcal</span></p>
          <p className="jb-body text-xs text-zinc-400 tabular-nums">P {Math.round(m.protein)}g · C {Math.round(m.carbs)}g · G {Math.round(m.fat)}g</p>
        </div>
        {preguntaAceite(food) && (
          <div className="bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-3 mb-4">
            <p className="jb-body text-sm text-zinc-200">{preguntaAceite(food).titulo}</p>
            <p className="jb-body text-[11px] text-zinc-500 mb-2">{preguntaAceite(food).ayuda}</p>
            <div className="flex flex-wrap gap-1.5" role="group" aria-label="Aceite">
              {preguntaAceite(food).opciones.map(o => {
                const activo = (en.aceite || 'normal') === o.key;
                return (
                  <button key={o.key} type="button" aria-pressed={activo}
                    onClick={() => updateEntry(meal, en.id, { aceite: o.key === 'normal' ? undefined : o.key })}
                    className={`jb-body text-xs px-3 py-1.5 rounded-full border whitespace-nowrap transition-colors ${activo ? 'bg-orange-500 border-orange-500 text-zinc-950 font-semibold' : 'border-zinc-700 text-zinc-300'}`}>
                    {o.label}
                  </button>
                );
              })}
            </div>
          </div>
        )}
        {onDesarmar && RECETAS_PLATOS[en.foodKey] && (() => {
          const partes = RECETAS_PLATOS[en.foodKey].map(([k]) => nombreAlimento(buscarFood(k)) || k);
          return (
            <button type="button" onClick={() => { onDesarmar(); onCerrar(); }}
              className="w-full bg-zinc-950 border border-orange-500/40 rounded-xl px-4 py-3 mb-4 text-left">
              <span className="block jb-body text-sm text-zinc-100">🧩 Ajustar ingredientes</span>
              <span className="block jb-body text-[11px] text-zinc-500 mt-0.5 leading-snug">
                ¿Le pusiste más o menos de algo? Se separa en {partes.join(', ')} y cambias lo que quieras.
              </span>
            </button>
          );
        })()}
        {food.esPersonal && onEditarPropio && (
          <button type="button" onClick={() => { onEditarPropio(food); onCerrar(); }}
            className="w-full jb-body text-xs text-orange-400 bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-2.5 mb-4 text-left">
            ✏️ Corregir los datos de este alimento (lo creaste tú)
          </button>
        )}

        {bucket && (
          <div className="mb-4">
            <button type="button" onClick={() => setVerSustitutos(v => !v)}
              className="w-full flex items-center justify-between jb-body text-sm text-zinc-200 bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-3">
              <span>🔄 Cambiar por otro equivalente</span>
              <ChevronRight size={16} className={`text-zinc-500 transition-transform ${verSustitutos ? 'rotate-90' : ''}`} />
            </button>
            {verSustitutos && (() => {
              const macro = bucket.macro;
              const valorObjetivo = m[macro];
              const gramosOriginal = entryGrams(en);
              return (
                <div className="mt-2">
                  <p className="jb-body text-[11px] text-zinc-500 mb-2">
                    La cantidad se ajusta sola para mantener la misma {MACRO_LABEL[macro]} ({valorObjetivo.toFixed(0)}g)
                  </p>
                  <div className="flex flex-col gap-1.5">
                    {opcionesOrdenadasPorPreferencia(food, username, mealPlan.restricciones || []).map(opt => {
                      const eq = sustitucionEquivalente(valorObjetivo, opt, macro);
                      const explicacion = explicarSustituto(food, gramosOriginal, opt, eq, macro);
                      return (
                        <button key={opt.key}
                          onClick={() => {
                            updateEntry(meal, en.id, { foodKey: opt.key, unit: eq.unit, qty: eq.qty, grams: undefined });
                            vibrar(20);
                            registrarPreferenciaSustituto(username, food.name, opt.name);
                            showToast(`🔄 Cambiado a ${opt.name} · ${eq.qty} ${eq.unit} para igualar tu ${MACRO_LABEL[macro]}`);
                            setVerSustitutos(false);
                          }}
                          className={`jb-body text-xs bg-zinc-950 border rounded-lg px-3 py-2 text-left flex items-center justify-between gap-2 ${opt.esPreferido ? 'border-orange-500/50' : 'border-zinc-800 hover:border-orange-500/40'}`}>
                          <span className="text-zinc-200">
                            {emojiAlimento(opt)} {opt.name} <span className="text-zinc-500">· {eq.qty} {eq.unit}</span>
                            {opt.esPreferido && <span className="text-orange-400 ml-1">⭐ tu preferido</span>}
                          </span>
                          <span className="text-zinc-600 text-[10px] shrink-0">{explicacion}</span>
                        </button>
                      );
                    })}
                  </div>
                </div>
              );
            })()}
          </div>
        )}

        <div className="mb-4">
          <p className="jb-body text-[11px] text-zinc-500 uppercase tracking-wider mb-2">¿Era otro alimento?</p>
          <BuscadorAlimento username={username} valor="" alimentos={todosLosAlimentos}
            onElegir={key => {
              const f = buscarFood(key);
              const d = unidadPorDefecto(f);
              if (en.fotoIA && key !== en.fotoIA) anotarCorreccionFoto(username, en.fotoIA, key, { despues: true });
              updateEntry(meal, en.id, { foodKey: key, unit: d.unit, qty: d.qty, grams: undefined, fotoIA: undefined });
            }}
            onNoEncuentra={texto => { onCrear(texto); onCerrar(); }} />
        </div>

        <div className="flex gap-2">
          <button type="button" onClick={() => { removeEntry(meal, en.id); onCerrar(); }}
            className="flex-1 jb-body text-sm text-red-400 border border-red-500/40 hover:bg-red-500/10 rounded-xl py-3 flex items-center justify-center gap-1.5">
            <Trash2 size={15} /> Quitar
          </button>
          <button type="button" onClick={onCerrar} className={btnPrimary + ' flex-[2] py-3'}>Listo</button>
        </div>
      </div>
    </div>
  );
}

// Ajuste avanzado del objetivo diario (kcal y % de macros). Vive en
// "Mi cuerpo → Objetivo"; en Comidas solo queda el aviso si no coincide.
function ObjetivoDiarioCard({ mealPlan, setMealPlan, targets, tdee }) {
  const [abierto, setAbierto] = useState(false);
  // Escribir las calorías y macros a mano es Premium. La meta calculada
  // según su objetivo es gratis.
  const { premium } = usePremium();
  const macroSum = mealPlan.macros.p + mealPlan.macros.c + mealPlan.macros.f;
  const goalMismatch = targets && Math.abs(mealPlan.targetKcal - targets.kcal) > 5;

  function applyGoal() {
    if (!targets || !targets.kcal) return;
    setMealPlan(v => ({ ...v, ...metaDesdeObjetivo(targets) }));
  }

  return (
    <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-5">
      <button onClick={() => setAbierto(v => !v)} className="w-full flex items-center justify-between gap-3 text-left">
        <div className="min-w-0">
          <h2 className="jb-display text-base text-zinc-200 mb-1 flex items-center gap-1.5">
            AJUSTE FINO DE CALORÍAS Y MACROS
            {goalMismatch && <span className="w-1.5 h-1.5 rounded-full bg-amber-500 shrink-0" title="No coincide con tu objetivo" />}
          </h2>
          <p className="jb-body text-xs text-zinc-500 truncate">
            Lo que usa tu registro de comidas: <span className="text-orange-500 font-semibold">{Math.round(mealPlan.targetKcal)} kcal</span> · P {Math.round(mealPlan.macros.p * 100)}% · C {Math.round(mealPlan.macros.c * 100)}% · G {Math.round(mealPlan.macros.f * 100)}%
          </p>
        </div>
        <ChevronRight className={`text-zinc-500 shrink-0 transition-transform ${abierto ? 'rotate-90' : ''}`} size={18} />
      </button>
      {abierto && !premium && (
        <div className="mt-4">
          <BloqueoPremium compacto titulo="Ajustar tu meta a mano es Premium"
            texto="Tu meta ya está calculada según tu cuerpo y tu objetivo. Con Premium puedes escribir tus propias calorías y macros.">
            {goalMismatch && (
              <button onClick={applyGoal} className="jb-body w-full mt-2 rounded-xl border border-zinc-700 text-zinc-200 py-2 text-sm">
                Usar mi objetivo ({Math.round(targets.kcal)} kcal)
              </button>
            )}
          </BloqueoPremium>
        </div>
      )}
      {abierto && premium && (
        <div className="mt-4">
          {goalMismatch && (
            <div className="bg-amber-950/40 border border-amber-800/50 rounded-xl p-3 flex items-center gap-2 mb-4">
              <AlertTriangle className="text-amber-500 shrink-0" size={16} />
              <p className="text-amber-200 text-xs jb-body">Estos valores no coinciden con tu objetivo ({Math.round(targets.kcal)} kcal). Toca "Usar mi objetivo" para sincronizarlos.</p>
            </div>
          )}
          {/* Calorías con la regla; proteína y grasas en % con su regla y los
              carbohidratos se calculan solos (lo que falta para 100%). */}
          {(() => {
            const kcal = Math.round(mealPlan.targetKcal) || 0;
            const p = Math.round((mealPlan.macros.p || 0) * 100);
            const f = Math.round((mealPlan.macros.f || 0) * 100);
            const c = Math.max(0, 100 - p - f);
            const fijarMacros = (np, nf) => {
              const pp = Math.max(10, Math.min(60, np)), ff = Math.max(10, Math.min(60, nf));
              const cc = Math.max(0, 100 - pp - ff);
              setMealPlan(v => ({ ...v, macros: { p: pp / 100, c: cc / 100, f: ff / 100 }, metaManual: true }));
            };
            return (
              <div className="flex flex-col gap-3">
                <CampoNumero label="Calorías al día" valor={kcal} paso={10} min={1000} max={5000} inicial={2000} unidad="kcal"
                  onCambio={n => setMealPlan(v => ({ ...v, targetKcal: Number(n) || 0, metaManual: true }))} />
                <div className="grid sm:grid-cols-2 gap-3">
                  <CampoNumero label={`Proteína · ${Math.round(kcal * p / 100 / 4)} g`} valor={p} paso={1} min={10} max={60} inicial={30} unidad="% de tus calorías"
                    onCambio={n => fijarMacros(Number(n) || 0, f)} />
                  <CampoNumero label={`Grasas · ${Math.round(kcal * f / 100 / 9)} g`} valor={f} paso={1} min={10} max={60} inicial={30} unidad="% de tus calorías"
                    onCambio={n => fijarMacros(p, Number(n) || 0)} />
                </div>
                <div className="bg-zinc-950 border border-zinc-800 rounded-2xl px-4 py-3 flex items-center justify-between">
                  <span className="jb-body text-xs text-zinc-400 uppercase tracking-wider">Carbohidratos (se calculan solos)</span>
                  <span className="jb-display text-xl text-zinc-50 tabular-nums">{c}% <span className="jb-body text-xs text-zinc-400">· {Math.round(kcal * c / 100 / 4)} g</span></span>
                </div>
                {targets ? (
                  <button onClick={applyGoal} className={btnPrimary + ' text-sm'}>
                    <Target size={14} /> Usar mi objetivo ({Math.round(targets.kcal)})
                  </button>
                ) : tdee ? (
                  <button onClick={() => setMealPlan(v => ({ ...v, targetKcal: Math.round(tdee) }))} className={btnGhost + ' text-sm'}>
                    <Flame size={14} /> Usar mi mantenimiento ({Math.round(tdee)})
                  </button>
                ) : null}
              </div>
            );
          })()}
        </div>
      )}
    </div>
  );
}

/* Comidas con la tira de días de arriba: hoy y los 6 días anteriores. Un
   día anterior se ve y se corrige igual que hoy; lo que cambie se guarda
   en el historial de ese día (solo sus comidas: su peso de ese día no se
   toca). */
function nombreDia(iso, hoy) {
  if (iso === hoy) return 'hoy';
  if (iso === addDaysISO(hoy, -1)) return 'ayer';
  const [y, m, d] = iso.split('-').map(Number);
  const dia = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'][new Date(y, m - 1, d).getDay()];
  return `el ${dia} ${d}`;
}
function totalesDelPlan(plan) {
  const t = { kcal: 0, protein: 0, carbs: 0, fat: 0 };
  let comidas = 0, alimentos = 0;
  Object.values(plan?.meals || {}).forEach(lista => {
    const con = (lista || []).filter(en => en.foodKey);
    if (con.length) comidas += 1;
    alimentos += con.length;
    (lista || []).forEach(en => { const m = entryMacros(en); t.kcal += m.kcal; t.protein += m.protein; t.carbs += m.carbs; t.fat += m.fat; });
  });
  return { t, comidas, alimentos };
}
function MealTab(props) {
  const { mealPlan, username, hojaInicial } = props;
  const hoy = todayISO();
  const [fecha, setFecha] = useState(hoy);
  const [resumen, setResumen] = useState({}); // fecha -> kcal del día (para la tira)
  const [plan, setPlan] = useState(null); // plan del día anterior abierto
  const [cargando, setCargando] = useState(false);
  const espera = useRef(null);
  const pendiente = useRef(null); // { f, p } cambio de un día anterior aún sin subir
  const dias = Array.from({ length: 7 }, (_, i) => addDaysISO(hoy, i - 6));
  // Si cambia de día (o sale de Comidas) con un cambio sin subir, se sube ya.
  function subirPendiente() {
    clearTimeout(espera.current);
    const x = pendiente.current;
    pendiente.current = null;
    if (x) guardarDia(x.f, x.p);
  }

  // Un pedido de registrar (desde Inicio o un aviso) siempre es para hoy.
  useEffect(() => { if (hojaInicial?.meal) setFecha(hoy); }, [hojaInicial?.id]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (!username) return;
    supabase.from('historial').select('fecha, kcal_consumidas, comidas_count').eq('username', username)
      .gte('fecha', dias[0]).lt('fecha', hoy)
      .then(({ data }) => setResumen(Object.fromEntries((data || []).map(r => [String(r.fecha).slice(0, 10), Number(r.comidas_count) > 0 ? Math.round(Number(r.kcal_consumidas) || 0) : 0]))))
      .catch(() => {});
  }, [username, hoy]); // eslint-disable-line react-hooks/exhaustive-deps

  async function abrirDia(f) {
    vibrar(8);
    subirPendiente();
    setFecha(f);
    if (f === hoy) { setPlan(null); return; }
    setCargando(true); setPlan(null);
    try {
      const { data } = await supabase.from('historial').select('meal_plan').eq('username', username).eq('fecha', f).maybeSingle();
      const guardado = data?.meal_plan;
      const vacias = Object.fromEntries(MEAL_NAMES.map(ml => [ml, []]));
      setPlan(guardado?.meals
        ? { ...mealPlan, ...guardado, meals: { ...vacias, ...guardado.meals } }
        : { ...mealPlan, meals: vacias });
    } catch {
      showToast('No se pudo abrir ese día. Revisa tu internet.', 'error');
      setFecha(hoy);
    }
    setCargando(false);
  }

  async function guardarDia(f, p) {
    const { t, comidas, alimentos } = totalesDelPlan(p);
    const { error } = await supabase.from('historial').upsert({
      username, fecha: f, meal_plan: p,
      kcal_consumidas: Math.round(t.kcal), proteina_g: Math.round(t.protein), carbos_g: Math.round(t.carbs), grasas_g: Math.round(t.fat),
      kcal_objetivo: Math.round(p.targetKcal) || null, comidas_count: comidas, alimentos_count: alimentos,
      updated_at: new Date().toISOString(),
    }, { onConflict: 'username,fecha' });
    if (error) { showToast(`No se pudo guardar ${nombreDia(f, hoy)}. Revisa tu internet e intenta de nuevo.`, 'error'); return; }
    setResumen(r => ({ ...r, [f]: comidas ? Math.round(t.kcal) : 0 }));
  }

  // Cambios en un día anterior: se guardan solos (al segundo de dejar de tocar).
  function setPlanDia(cambio) {
    setPlan(p => {
      const nuevo = typeof cambio === 'function' ? cambio(p) : cambio;
      clearTimeout(espera.current);
      pendiente.current = { f: fecha, p: nuevo };
      espera.current = setTimeout(subirPendiente, 800);
      return nuevo;
    });
  }
  useEffect(() => () => subirPendiente(), []); // eslint-disable-line react-hooks/exhaustive-deps

  const esHoy = fecha === hoy;
  const kcalHoy = Math.round(totalesDelPlan(mealPlan).t.kcal);
  return (
    <div className="flex flex-col gap-3 min-w-0">
      <div className="grid grid-cols-7 gap-1" role="tablist" aria-label="Elegir día">
        {dias.map(f => {
          const [y, m, d] = f.split('-').map(Number);
          const activo = f === fecha;
          const kcal = f === hoy ? kcalHoy : resumen[f] || 0;
          return (
            <button key={f} role="tab" aria-selected={activo} onClick={() => abrirDia(f)}
              className={`rounded-xl py-1.5 flex flex-col items-center border transition-colors ${activo ? 'bg-orange-500 border-orange-500 text-zinc-950' : 'bg-zinc-900 border-zinc-800 text-zinc-300'}`}>
              <span className={`jb-body text-[10px] uppercase ${activo ? 'text-zinc-900' : 'text-zinc-500'}`}>{f === hoy ? 'Hoy' : ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'][new Date(y, m - 1, d).getDay()]}</span>
              <span className="jb-display text-base leading-tight tabular-nums">{d}</span>
              <span className={`w-1.5 h-1.5 rounded-full mt-0.5 ${kcal > 0 ? (activo ? 'bg-zinc-950' : 'bg-emerald-500') : 'bg-transparent'}`} />
            </button>
          );
        })}
      </div>
      {!esHoy && (
        <div className="bg-orange-500/10 border border-orange-500/40 rounded-xl px-3 py-2.5 flex items-center gap-2">
          <p className="jb-body text-xs text-orange-200 flex-1">Estás viendo <b>{nombreDia(fecha, hoy)}</b>. Lo que agregues o cambies se guarda en ese día.</p>
          <button onClick={() => abrirDia(hoy)} className="jb-body text-xs font-semibold text-zinc-950 bg-orange-500 rounded-full px-3 py-1.5 shrink-0">Volver a hoy</button>
        </div>
      )}
      {esHoy ? <MealTabDia {...props} /> : cargando || !plan ? (
        <div className="flex flex-col gap-3">{[0, 1, 2].map(i => <Skeleton key={i} className="h-16 w-full rounded-2xl" />)}</div>
      ) : (
        <MealTabDia key={fecha} {...props} mealPlan={plan} setMealPlan={setPlanDia} esHoy={false} hojaInicial={null} />
      )}
    </div>
  );
}

function MealTabDia({ mealPlan, setMealPlan, tdee, targets, username, hojaInicial = null, onVerPlanes = null, esHoy = true, peso = null }) {
  const [personales, setPersonales] = useState([]);
  // Aviso de que se revisó un alimento suyo (tarjeta arriba, no un toast:
  // así alcanza a leerlo y, en la versión gratis, ve lo que da Premium).
  const [avisoPropio, setAvisoPropio] = useState(null);
  const { premium, onVerPremium } = usePremium();
  const [editarPropio, setEditarPropio] = useState(null);
  const [escribiendo, setEscribiendo] = useState(false);
  useEffect(() => {
    const esCampo = el => el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA');
    const alEnfocar = e => { if (esCampo(e.target)) setEscribiendo(true); };
    const alSalir = () => setTimeout(() => setEscribiendo(esCampo(document.activeElement)), 200);
    document.addEventListener('focusin', alEnfocar);
    document.addEventListener('focusout', alSalir);
    return () => { document.removeEventListener('focusin', alEnfocar); document.removeEventListener('focusout', alSalir); };
  }, []);
  const [crearPara, setCrearPara] = useState(null); // {meal, id, texto}
  const [editando, setEditando] = useState(null); // { meal, id } del alimento abierto en el panel de edición
  const [swipe, setSwipe] = useState({}); // id -> { dx, startX }
  const [fotoPara, setFotoPara] = useState(null); // nombre de la comida para la que se abrió el modal de foto
  const [codigoPara, setCodigoPara] = useState(null); // ídem, para el escáner de código de barras
  // Destello al completar una comida (cuando recibe su primer alimento).
  const [destellos, setDestellos] = useState({});
  const conteosPrevios = useRef(null);
  useEffect(() => {
    const conteos = Object.fromEntries(MEAL_NAMES.map(ml => [ml, (mealPlan.meals[ml] || []).filter(e => e.foodKey).length]));
    const previos = conteosPrevios.current;
    if (previos) {
      const nuevos = MEAL_NAMES.filter(ml => previos[ml] === 0 && conteos[ml] > 0);
      if (nuevos.length) {
        vibrar(25);
        setDestellos(d => ({ ...d, ...Object.fromEntries(nuevos.map(ml => [ml, Date.now()])) }));
      }
    }
    conteosPrevios.current = conteos;
  }, [mealPlan]);
  const [hojaMeal, setHojaMeal] = useState(hojaInicial?.foto || hojaInicial?.escribir ? null : hojaInicial?.meal || null); // comida elegida en la hoja "Registrar" (null = cerrada)
  // Pedido de registrar que llega estando ya en Comidas (ej. desde un aviso).
  useEffect(() => {
    if (!hojaInicial?.meal) return;
    if (hojaInicial.foto) { setHojaMeal(null); setFotoPara(hojaInicial.meal); }
    else if (hojaInicial.escribir) { setHojaMeal(null); setEscribirPara(hojaInicial.meal); }
    else setHojaMeal(hojaInicial.meal);
  }, [hojaInicial?.id]);
  const [enfocar, setEnfocar] = useState(null); // id de la entrada nueva a la que llevar al alumno
  const [recien, setRecien] = useState([]); // ids recién registrados (se resaltan 3 segundos)
  // Al terminar de registrar por cualquier camino (hoja, voz, foto, código,
  // escribir), la pantalla va a lo que se agregó y lo marca en verde: antes,
  // con la foto, quedaba más abajo (en Cena o Agua) y no se veía.
  const flujo = useRef(null); // { meal, antes: Set de ids que ya estaban }
  const [escribirPara, setEscribirPara] = useState(null); // comida abierta en el registro escrito
  const [textoInicial, setTextoInicial] = useState({}); // id de fila -> texto ya escrito (de "Buscarlo de otra forma")
  const mealAhora = esHoy ? comidaDeAhora() : null;
  // Comidas que ya pasaron: las registradas se ven cerradas en una línea
  // (se abren tocándolas) y las que no se registraron se juntan en una sola
  // línea delgada, para llegar a la comida de AHORA sin bajar tanto.
  const idxAhora = MEAL_NAMES.indexOf(mealAhora);
  const [abiertas, setAbiertas] = useState({}); // comida pasada -> true si el alumno la abrió
  const [eligiendoSaltada, setEligiendoSaltada] = useState(false);
  const saltadas = MEAL_NAMES.filter((m, i) => i < idxAhora && !(mealPlan.meals[m] || []).length);
  // La comida a la que se le está agregando algo queda abierta, para ver lo
  // que se agregó.
  useEffect(() => {
    const m = hojaMeal || fotoPara || codigoPara || escribirPara;
    if (m) {
      if (!flujo.current || flujo.current.meal !== m) flujo.current = { meal: m, antes: new Set((mealPlan.meals[m] || []).map(e => e.id)) };
      return;
    }
    if (!flujo.current) return;
    const { meal, antes } = flujo.current;
    flujo.current = null;
    const agregadas = (mealPlan.meals[meal] || []).filter(e => !antes.has(e.id));
    const nuevos = agregadas.filter(e => e.foodKey).map(e => e.id);
    if (!nuevos.length) return;
    setRecien(nuevos);
    setTimeout(() => setRecien([]), 3000);
    // Si quedó una fila por buscar (voz: "No es ninguna"), la vista va a esa.
    if (agregadas.some(e => !e.foodKey)) return;
    setTimeout(() => {
      const el = document.getElementById('entrada-' + nuevos[nuevos.length - 1]);
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, 150);
  }, [hojaMeal, fotoPara, codigoPara, escribirPara]); // eslint-disable-line react-hooks/exhaustive-deps
  // Al terminar de registrar, esa comida (pasada o la de AHORA) se cierra sola a los 6
  // segundos (lo justo para ver lo agregado en verde): así la pantalla queda
  // ordenada y no hay que bajar tanto. No se cierra si el alumno sigue
  // haciendo algo (editando, escribiendo) o si quedó un alimento por buscar.
  // También al abrirla tocándola: se cierra sola a los 8 segundos sin tocar
  // nada (cada cambio de cantidad vuelve a contar).
  const abiertaPorRegistro = useRef(null);
  const esperaCierre = useRef(6000);
  useEffect(() => {
    const m = hojaMeal || fotoPara || codigoPara || escribirPara;
    if (m && esHoy) {
      abiertaPorRegistro.current = m;
      esperaCierre.current = 6000;
      setAbiertas(a => (a[m] ? a : { ...a, [m]: true }));
    }
  }, [hojaMeal, fotoPara, codigoPara, escribirPara]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    const m = abiertaPorRegistro.current;
    if (!m || hojaMeal || fotoPara || codigoPara || escribirPara || crearPara || editando || escribiendo) return;
    const t = setTimeout(() => {
      if ((mealPlan.meals[m] || []).some(en => !en.foodKey)) return; // falta elegir un alimento
      abiertaPorRegistro.current = null;
      setAbiertas(a => ({ ...a, [m]: false }));
    }, esperaCierre.current);
    return () => clearTimeout(t);
  }, [hojaMeal, fotoPara, codigoPara, escribirPara, crearPara, editando, escribiendo, mealPlan, abiertas]); // eslint-disable-line react-hooks/exhaustive-deps
  // Al entrar a Comidas, si la comida de AHORA quedó fuera de la pantalla,
  // se baja hasta ella.
  useEffect(() => {
    if (hojaInicial?.meal) return;
    const t = setTimeout(() => {
      const el = document.getElementById('comida-ahora');
      if (el && el.getBoundingClientRect().top > window.innerHeight - 140) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, 350);
    return () => clearTimeout(t);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps
  const [ayudaCerrada, setAyudaCerrada] = useState(() => {
    try { return localStorage.getItem('jb_ayuda_no_comidas') === '1'; } catch { return false; }
  });

  // Sus alimentos propios. Si Jonah marcó que uno "ya existe en la app"
  // (columna reemplazo), deja de salir en su buscador y, en sus comidas, ese
  // nombre usa los datos del alimento de la app.
  async function cargarPersonales() {
    try {
      const { data } = await supabase.from('alimentos_personales')
        .select('*').eq('username', username).order('created_at', { ascending: false }).limit(200);
      const filas = data || [];
      const lista = filas.filter(a => !a.reemplazo).map(a => ({
        key: a.nombre + ' (mío)', name: a.nombre, group: 'Mis alimentos', state: '-',
        kcal: Number(a.kcal), protein: Number(a.proteina), carbs: Number(a.carbos),
        fat: Number(a.grasas), fiber: 0, esPersonal: true, idPropio: a.id,
      }));
      const reemplazos = filas.filter(a => a.reemplazo).map(a => {
        const oficial = FOODS.find(f => f.key === a.reemplazo);
        return oficial ? { ...oficial, key: a.nombre + ' (mío)', reemplazaA: a.nombre } : null;
      }).filter(Boolean);
      setPersonales(lista);
      setFoodsPersonales([...lista, ...reemplazos]);
      // Avisos (una vez) de lo que cambió Jonah.
      try {
        const visto = localStorage.getItem('jb_alim_corregido_visto') || '';
        const nuevos = filas.filter(a => ['corregido', 'existe', 'aprobado'].includes(a.revision) && a.revisado_en && a.revisado_en > visto);
        if (nuevos.length) {
          const a = nuevos[0];
          const oficial = a.reemplazo && FOODS.find(f => f.key === a.reemplazo);
          setAvisoPropio(oficial && a.revision === 'aprobado'
            ? `➕ ¡Gracias! Jonah revisó "${a.nombre}" y ya está en la app para todos. Tus comidas ya se actualizaron.`
            : oficial
            ? `🔗 "${a.nombre}" ya estaba en la app: lo cambiamos por "${oficial.name}". Tus comidas ya se actualizaron.`
            : `✏️ Revisamos "${a.nombre}"${nuevos.length > 1 ? ` y ${nuevos.length - 1} más` : ''} y corregimos sus calorías. Tus comidas ya se actualizaron.`);
          localStorage.setItem('jb_alim_corregido_visto', nuevos.map(x => x.revisado_en).sort().pop());
        }
      } catch {}
      await recalcularHistorialPropio(filas);
    } catch {}
  }

  // Los totales de días pasados (Progreso, tendencias) se guardan ya
  // sumados. Si un alimento suyo cambió (lo corrigió él o Jonah, o se
  // reemplazó por uno de la app), se vuelven a sumar los días donde lo usó.
  async function recalcularHistorialPropio(filas) {
    let hechos = {};
    try { hechos = JSON.parse(localStorage.getItem('jb_alim_recalculado') || '{}'); } catch {}
    const cambiados = filas.filter(a => {
      const marca = a.revisado_en || a.editado_en;
      return marca && hechos[a.id] !== marca;
    });
    if (!cambiados.length) return;
    try {
      const { data: dias } = await traerTodas(() => supabase.from('historial').select('fecha, meal_plan').eq('username', username));
      const claves = cambiados.map(a => a.nombre + ' (mío)');
      for (const d of dias || []) {
        const texto = JSON.stringify(d.meal_plan || {});
        if (!claves.some(k => texto.includes(JSON.stringify(k)))) continue;
        const t = { kcal: 0, protein: 0, carbs: 0, fat: 0 };
        Object.values(d.meal_plan?.meals || {}).forEach(entries => (entries || []).forEach(en => {
          const m = entryMacros(en);
          t.kcal += m.kcal; t.protein += m.protein; t.carbs += m.carbs; t.fat += m.fat;
        }));
        await supabase.from('historial').update({
          kcal_consumidas: Math.round(t.kcal), proteina_g: Math.round(t.protein),
          carbos_g: Math.round(t.carbs), grasas_g: Math.round(t.fat),
        }).eq('username', username).eq('fecha', d.fecha);
      }
      cambiados.forEach(a => { hechos[a.id] = a.revisado_en || a.editado_en; });
      localStorage.setItem('jb_alim_recalculado', JSON.stringify(hechos));
    } catch {}
  }

  const versionAlimentos = usarAlimentosExtra();
  // Se vuelve a cargar cuando llegan los alimentos que agregó Jonah: un
  // alimento propio puede estar reemplazado por uno de ellos.
  useEffect(() => { if (username) cargarPersonales(); }, [username, versionAlimentos]);
  const todosLosAlimentos = useMemo(() => [...personales, ...foodsBuscador()], [personales, versionAlimentos]);
  const totals = useMemo(() => {
    const t = { kcal: 0, protein: 0, carbs: 0, fat: 0 };
    Object.values(mealPlan.meals).forEach(entries => entries.forEach(en => {
      const m = entryMacros(en);
      t.kcal += m.kcal; t.protein += m.protein; t.carbs += m.carbs; t.fat += m.fat;
    }));
    return t;
  }, [mealPlan, versionAlimentos]);

  const objP = (mealPlan.targetKcal * mealPlan.macros.p) / 4;
  const objC = (mealPlan.targetKcal * mealPlan.macros.c) / 4;
  const objF = (mealPlan.targetKcal * mealPlan.macros.f) / 9;

  function updateEntry(meal, id, patch) {
    setMealPlan(v => ({
      ...v,
      meals: { ...v.meals, [meal]: v.meals[meal].map(en => en.id === id ? { ...en, ...patch } : en) },
    }));
  }
  function addEntry(meal) {
    const id = uid();
    setMealPlan(v => ({ ...v, meals: { ...v.meals, [meal]: [...v.meals[meal], { id, foodKey: '', qty: 100, unit: 'gramos' }] } }));
    return id;
  }

  // Al elegir "Escribir" en la hoja: se crea la fila vacía y se lleva al
  // alumno hasta ella con el buscador listo para escribir.
  useEffect(() => {
    if (!enfocar) return;
    const el = document.getElementById('entrada-' + enfocar);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }, [enfocar]);
  function removeEntry(meal, id) {
    setMealPlan(v => ({ ...v, meals: { ...v.meals, [meal]: v.meals[meal].filter(en => en.id !== id) } }));
  }
  // Quitar un alimento con "DESHACER" por 5 segundos: si fue sin querer,
  // vuelve a su lugar con su misma cantidad.
  function quitarConDeshacer(meal, id) {
    const lista = mealPlan.meals[meal] || [];
    const pos = lista.findIndex(x => x.id === id);
    const quitado = lista[pos];
    removeEntry(meal, id);
    if (!quitado?.foodKey) return;
    const food = buscarFood(quitado.foodKey);
    vibrar(15);
    showToast(`🗑️ Quitaste ${food ? nombreAlimento(food) : 'el alimento'}`, 'success', {
      accion: {
        texto: 'DESHACER',
        alHacer: () => {
          vibrar(10);
          setMealPlan(v => {
            const actual = [...(v.meals[meal] || [])];
            if (actual.some(x => x.id === quitado.id)) return v;
            actual.splice(Math.min(pos, actual.length), 0, quitado);
            return { ...v, meals: { ...v.meals, [meal]: actual } };
          });
        },
      },
    });
  }
  // "🧩 Ajustar ingredientes": el plato se cambia, en su lugar, por sus partes.
  function desarmarPlato(meal, en) {
    const partes = partesDelPlato(en);
    if (!partes) return;
    vibrar(20);
    setMealPlan(v => ({ ...v, meals: { ...v.meals, [meal]: v.meals[meal].flatMap(x => x.id === en.id ? partes : [x]) } }));
    showToast(`🧩 Separado en ${partes.length} ingredientes: cambia la cantidad de cada uno con − y +`);
  }

  const SWIPE_UMBRAL = -70; // px hacia la izquierda para eliminar
  function onSwipeStart(id, clientX) {
    setSwipe(v => ({ ...v, [id]: { startX: clientX, dx: 0 } }));
  }
  function onSwipeMove(id, clientX) {
    setSwipe(v => {
      const s = v[id];
      if (!s) return v;
      const dx = Math.min(0, clientX - s.startX);
      return { ...v, [id]: { ...s, dx } };
    });
  }
  function onSwipeEnd(meal, id) {
    const s = swipe[id];
    if (s && s.dx <= SWIPE_UMBRAL) quitarConDeshacer(meal, id);
    setSwipe(v => {
      const { [id]: _, ...resto } = v;
      return resto;
    });
  }

  function applyGoal() {
    if (!targets || !targets.kcal) return;
    setMealPlan(v => ({ ...v, ...metaDesdeObjetivo(targets) }));
  }

  const goalMismatch = targets && Math.abs(mealPlan.targetKcal - targets.kcal) > 5;

  return (
    <div className="flex flex-col gap-4 min-w-0 pb-16">
      <style>{ESTILOS_COMIDAS}</style>
      <MedidorComidas totals={totals} targetKcal={mealPlan.targetKcal} objP={objP} objC={objC} objF={objF} />
      {avisoPropio && (
        <div className="bg-zinc-900 border border-orange-500/40 rounded-2xl p-4 flex flex-col gap-2">
          <p className="jb-body text-sm text-zinc-100">{avisoPropio}</p>
          {!premium && onVerPremium && (
            <p className="jb-body text-xs text-zinc-400">👑 Con Premium no tienes ni que crearlos: me pides lo que no encuentres y yo te lo agrego con todo calculado. — Jonah</p>
          )}
          <div className="flex gap-2 mt-1">
            {!premium && onVerPremium && (
              <button onClick={() => { registrarPasoPago('alimento_revisado', username, 'ver_premium'); setAvisoPropio(null); onVerPremium(); }}
                className={btnPrimary + ' flex-1 py-2.5 text-sm'}>Ver Premium</button>
            )}
            <button onClick={() => setAvisoPropio(null)}
              className={(!premium && onVerPremium ? btnGhost : btnPrimary) + ' flex-1 py-2.5 text-sm'}>Entendido</button>
          </div>
        </div>
      )}
      {esHoy && <MenuDelDia mealPlan={mealPlan} setMealPlan={setMealPlan} username={username} />}
      {hojaMeal && (
        <HojaRegistrar
          meal={hojaMeal} setMeal={setHojaMeal} onCerrar={() => setHojaMeal(null)}
          onFoto={m => { setHojaMeal(null); setFotoPara(m); }}
          onCodigo={m => { setHojaMeal(null); setCodigoPara(m); }}
          onEscribir={m => { setHojaMeal(null); setEscribirPara(m); }}
          onAgregado={() => setHojaMeal(null)} // al cerrarse, la vista baja a lo agregado (ver "flujo")
          onBuscarDespues={(m, textos) => {
            // Lo que dijo por voz y no está (o "No es ninguna"): una fila por
            // cada uno, con el buscador ya escrito ("Pedirle a Jonah" incluido).
            setHojaMeal(null);
            let ultimo = null;
            textos.forEach(t => { const id = addEntry(m); ultimo = id; setTextoInicial(v => ({ ...v, [id]: t })); });
            if (ultimo) setEnfocar(ultimo);
          }}
          username={username} mealPlan={mealPlan} setMealPlan={setMealPlan}
        />
      )}
      {escribirPara && (
        <RegistroEscritoModal meal={escribirPara} username={username} todosLosAlimentos={todosLosAlimentos}
          mealPlan={mealPlan} setMealPlan={setMealPlan}
          onOtraForma={texto => { const m = escribirPara; setEscribirPara(null); const id = addEntry(m); setTextoInicial(t => ({ ...t, [id]: texto })); setEnfocar(id); }}
          onCerrar={() => setEscribirPara(null)}
          onCambiarComida={m => { if (m !== escribirPara) setAbiertas(a => ({ ...a, [escribirPara]: false })); setEscribirPara(m); }} />
      )}
      {/* Botón principal para registrar: uno solo, siempre a mano (se
          esconde mientras escribe, para no tapar la lista del buscador). */}
      {!hojaMeal && !fotoPara && !codigoPara && !crearPara && !editando && !escribiendo && !escribirPara && (
        <button onClick={() => { vibrar(10); setHojaMeal(mealAhora || comidaDeAhora()); }}
          className="jbm-fab fixed left-1/2 -translate-x-1/2 bottom-24 z-40 bg-orange-500 hover:bg-orange-400 text-zinc-950 rounded-full pl-4 pr-5 py-3 flex items-center gap-2 transition-colors"
          aria-label="Registrar comida">
          <Plus size={20} strokeWidth={2.6} />
          <span className="jb-display text-sm tracking-wide">REGISTRAR</span>
        </button>
      )}
      {editando && (() => {
        const en = (mealPlan.meals[editando.meal] || []).find(x => x.id === editando.id);
        return en ? (
          <HojaEditarAlimento meal={editando.meal} en={en} todosLosAlimentos={todosLosAlimentos}
            username={username} mealPlan={mealPlan} updateEntry={updateEntry} removeEntry={quitarConDeshacer}
            onCrear={texto => setCrearPara({ meal: editando.meal, id: en.id, texto })}
            onEditarPropio={food => setEditarPropio(food)}
            onDesarmar={() => desarmarPlato(editando.meal, en)}
            onCerrar={() => setEditando(null)} />
        ) : null;
      })()}
      {crearPara && (
        <CrearAlimentoModal
          username={username}
          nombreInicial={crearPara.texto}
          onCerrar={() => setCrearPara(null)}
          onRevisado={cargarPersonales}
          onCreado={async (nombre) => {
            await cargarPersonales();
            const nuevo = (nombre || crearPara.texto).trim() + ' (mío)';
            updateEntry(crearPara.meal, crearPara.id, { foodKey: nuevo, unit: 'gramos', qty: 100, grams: undefined });
          }}
          onElegirExistente={food => {
            const u = unidadPorDefecto(food);
            updateEntry(crearPara.meal, crearPara.id, { foodKey: food.key, unit: u.unit, qty: u.qty, grams: undefined });
          }}
        />
      )}
      {editarPropio && (
        <CrearAlimentoModal username={username} editar={editarPropio}
          onCerrar={() => setEditarPropio(null)} onRevisado={cargarPersonales}
          onCreado={async () => { await cargarPersonales(); showToast('✅ Alimento corregido'); }} />
      )}
      {codigoPara && (
        <EscanearCodigoModal
          meal={codigoPara}
          onCerrar={() => setCodigoPara(null)}
          onEscribir={() => { const m = codigoPara; setCodigoPara(null); setEscribirPara(m); }}
          onAgregar={(entry) => setMealPlan(v => ({ ...v, meals: { ...v.meals, [codigoPara]: [...v.meals[codigoPara], entry] } }))}
        />
      )}
      {fotoPara && (
        <ReconocerFotoModal
          username={username}
          comida={fotoPara}
          todosLosAlimentos={todosLosAlimentos}
          onVerPlanes={onVerPlanes ? () => { setFotoPara(null); onVerPlanes(); } : null}
          onCerrar={() => setFotoPara(null)}
          onEscribir={() => { const m = fotoPara; setFotoPara(null); setEscribirPara(m); }}
          onCambiarComida={m => { if (m !== fotoPara) setAbiertas(a => ({ ...a, [fotoPara]: false })); setFotoPara(m); }}
          onAgregar={(entry) => setMealPlan(v => ({ ...v, meals: { ...v.meals, [fotoPara]: [...v.meals[fotoPara], entry] } }))}
          onQuitar={(ids) => setMealPlan(v => ({ ...v, meals: { ...v.meals, [fotoPara]: v.meals[fotoPara].filter(e => !ids.includes(e.id)) } }))}
        />
      )}
      {!ayudaCerrada && (
        <div className="bg-zinc-900/60 border border-zinc-800 rounded-xl p-3 flex items-start gap-2.5">
          <span className="w-6 h-6 rounded-full bg-orange-500/15 border border-orange-500/30 flex items-center justify-center text-xs shrink-0 mt-0.5">💡</span>
          <div className="flex-1">
            <p className="jb-body text-xs text-zinc-400">Toca <span className="text-orange-400 font-semibold">+ Registrar</span> y agrega lo que comiste con foto, voz o escribiendo, con medidas de casa (taza, plato, unidad). No necesitas pesar nada. Arriba ves siempre cuánto te queda del día.</p>
            <p className="jb-body text-[11px] text-zinc-500 mt-1.5">Los platos preparados (ají de gallina, ceviche, pollo a la brasa…) son estimaciones promedio — úsalos como referencia, no como medida exacta.</p>
          </div>
          <button onClick={() => { setAyudaCerrada(true); try { localStorage.setItem('jb_ayuda_no_comidas', '1'); } catch {} }}
            className="text-zinc-600 hover:text-zinc-400 shrink-0 p-2.5 -m-1.5" aria-label="Cerrar"><X size={16} /></button>
        </div>
      )}


      {MEAL_NAMES.map((meal, idx) => {
        const entradas = mealPlan.meals[meal];
        const vacia = entradas.length === 0;
        const esAhora = meal === mealAhora;
        const pasada = idx < idxAhora;
        // Hoy, toda comida con algo registrado se ve cerrada en una línea
        // (también la de AHORA: si ya la registró, ya está hecha; para
        // agregar más la abre). No se cierra si quedó un alimento por buscar.
        const plegable = esHoy && !vacia && !entradas.some(en => !en.foodKey);
        const kcalComida = entradas.reduce((a, en) => a + entryMacros(en).kcal, 0);
        // Ya pasó y no se registró: todas juntas en una línea delgada, en el
        // lugar de la última.
        if (pasada && vacia) {
          if (meal !== saltadas[saltadas.length - 1]) return null;
          const nombres = saltadas.length === 1 ? saltadas[0]
            : `${saltadas.slice(0, -1).join(', ')} y ${saltadas[saltadas.length - 1]}`;
          return (
            <div key="saltadas" className="px-1 -my-1">
              <div className="flex items-center gap-2">
                <span className="text-sm opacity-60 shrink-0">{saltadas.map(m => ICONO_COMIDA[m]).join('')}</span>
                <p className="jb-body text-xs text-zinc-500 flex-1 min-w-0">{nombres} — {saltadas.length === 1 ? 'no registrada' : 'no registradas'}</p>
                <button onClick={() => { vibrar(10); if (saltadas.length === 1) setHojaMeal(saltadas[0]); else setEligiendoSaltada(v => !v); }}
                  aria-label={`Agregar a ${nombres}`}
                  className="w-8 h-8 rounded-full flex items-center justify-center shrink-0 bg-zinc-950 border border-zinc-700 text-zinc-400 hover:text-orange-400 hover:border-orange-500/40">
                  <Plus size={16} strokeWidth={2.4} />
                </button>
              </div>
              {eligiendoSaltada && saltadas.length > 1 && (
                <div className="flex flex-wrap gap-2 mt-2">
                  <span className="jb-body text-[11px] text-zinc-500 self-center">¿A cuál?</span>
                  {saltadas.map(m => (
                    <button key={m} onClick={() => { setEligiendoSaltada(false); setHojaMeal(m); }}
                      className="jb-body text-xs px-3 py-1.5 rounded-full border border-orange-500/40 bg-zinc-950 text-zinc-200 flex items-center gap-1.5">
                      <span>{ICONO_COMIDA[m]}</span>{m}
                    </button>
                  ))}
                </div>
              )}
            </div>
          );
        }
        // Tiene lo registrado: cerrada en una línea; se abre al tocarla.
        if (plegable && !abiertas[meal]) {
          return (
            <button key={meal} id={esAhora ? 'comida-ahora' : undefined} onClick={() => { vibrar(8); abiertaPorRegistro.current = meal; esperaCierre.current = 8000; setAbiertas(a => ({ ...a, [meal]: true })); }}
              aria-label={`Ver ${meal}`}
              className={`w-full bg-zinc-900 border rounded-2xl px-4 py-2.5 flex items-center gap-2.5 text-left hover:border-orange-500/40 ${esAhora ? 'border-orange-500/50' : 'border-zinc-800'}`}>
              <span className="relative w-8 h-8 rounded-full flex items-center justify-center text-sm shrink-0 border bg-orange-500/20 border-orange-500/40">
                {ICONO_COMIDA[meal] || '🍴'}
                <span className="absolute -bottom-1 -right-1 w-4 h-4 rounded-full bg-emerald-500 text-zinc-950 text-[10px] font-bold flex items-center justify-center border-2 border-zinc-900">✓</span>
              </span>
              <span className="flex-1 min-w-0">
                <span className="jb-display text-sm tracking-wide text-orange-500 flex items-center gap-2">
                  {meal.toUpperCase()}
                  {esAhora && <span className="jb-body text-[9px] font-semibold tracking-wider text-zinc-950 bg-orange-500 rounded-full px-1.5 py-0.5">AHORA</span>}
                </span>
                <span className="jb-body text-[11px] text-zinc-500 tabular-nums block">{entradas.length} {entradas.length === 1 ? 'alimento' : 'alimentos'} · <span className="text-zinc-300">{Math.round(kcalComida)} kcal</span></span>
              </span>
              <ChevronRight size={18} className="text-zinc-500 shrink-0" />
            </button>
          );
        }
        return (
        <div key={meal} id={esAhora ? 'comida-ahora' : undefined} className={`bg-zinc-900 border rounded-2xl ${vacia ? 'px-4 py-3' : 'p-4'} ${esAhora ? 'border-orange-500/50' : 'border-zinc-800'}`}
          style={esAhora ? { boxShadow: '0 0 22px rgba(232,89,12,.12)' } : undefined}>
          <div className={`flex items-center gap-2.5 ${vacia ? '' : 'mb-3'}`}>
            <div key={destellos[meal] || 0} className={`relative w-8 h-8 rounded-full flex items-center justify-center text-sm shrink-0 border ${vacia ? 'bg-zinc-800/60 border-zinc-700' : 'bg-orange-500/20 border-orange-500/40'} ${destellos[meal] ? 'jbm-completa' : ''}`}>
              {ICONO_COMIDA[meal] || '🍴'}
              {!vacia && (
                <span className="jbm-check absolute -bottom-1 -right-1 w-4 h-4 rounded-full bg-emerald-500 text-zinc-950 text-[10px] font-bold flex items-center justify-center border-2 border-zinc-900">✓</span>
              )}
              {destellos[meal] && <span className="jbm-onda absolute inset-0 rounded-full border-2 border-orange-400 pointer-events-none" />}
            </div>
            <div className="flex-1 min-w-0">
              <h3 className={`jb-display text-sm tracking-wide flex items-center gap-2 ${vacia ? 'text-zinc-400' : 'text-orange-500'}`}>
                {meal.toUpperCase()}
                {esAhora && <span className="jb-body text-[9px] font-semibold tracking-wider text-zinc-950 bg-orange-500 rounded-full px-1.5 py-0.5">AHORA</span>}
              </h3>
              {vacia
                ? <p className="jb-body text-[11px] text-zinc-600">{esAhora ? 'Es hora de registrar — toca +' : 'Sin registrar'}</p>
                : <p className="jb-body text-[11px] text-zinc-500 tabular-nums">{entradas.length} {entradas.length === 1 ? 'alimento' : 'alimentos'} · <span className="text-zinc-300">{Math.round(kcalComida)} kcal</span></p>}
            </div>
            {plegable && (
              <button onClick={() => { abiertaPorRegistro.current = null; setAbiertas(a => ({ ...a, [meal]: false })); }} aria-label={`Cerrar ${meal}`}
                className="w-8 h-8 rounded-full flex items-center justify-center shrink-0 text-zinc-500 hover:text-zinc-300">
                <ChevronDown size={18} />
              </button>
            )}
            <button onClick={() => { vibrar(10); setHojaMeal(meal); }} aria-label={`Agregar a ${meal}`}
              className={`w-9 h-9 rounded-full flex items-center justify-center shrink-0 transition-colors ${esAhora ? 'bg-orange-500 text-zinc-950 hover:bg-orange-400' : 'bg-zinc-950 border border-orange-500/40 text-orange-400 hover:bg-orange-500/10'}`}>
              <Plus size={18} strokeWidth={2.4} />
            </button>
          </div>
          {vacia ? null : (
            <div className="flex flex-col gap-1.5">
              {mealPlan.meals[meal].map(en => {
                const m = entryMacros(en);
                const food = buscarFood(en.foodKey);
                const swipeDx = (swipe[en.id] && swipe[en.id].dx) || 0;
                // Fila recién creada con "Escribir": todavía no tiene alimento.
                if (!food) {
                  return (
                    <div key={en.id} id={'entrada-' + en.id} className="bg-zinc-950 border border-orange-500/40 rounded-xl p-2 flex items-center gap-2">
                      <BuscadorAlimento username={username}
                        valor={textoInicial[en.id] || ''}
                        alimentos={todosLosAlimentos}
                        onElegir={key => {
                          const f = buscarFood(key);
                          const d = unidadPorDefecto(f);
                          updateEntry(meal, en.id, { foodKey: key, unit: d.unit, qty: d.qty, grams: undefined });
                          // Frito o saltado: se abre su panel para preguntar por el aceite.
                          if (esConAceite(f)) setEditando({ meal, id: en.id });
                        }}
                        onNoEncuentra={texto => setCrearPara({ meal, id: en.id, texto })}
                        autoFocus={enfocar === en.id}
                        pista
                      />
                      <button onClick={() => removeEntry(meal, en.id)} aria-label="Quitar"
                        className="text-zinc-600 hover:text-red-400 p-2 shrink-0"><Trash2 size={16} /></button>
                    </div>
                  );
                }
                const porcion = porcionDeEntrada(en);
                const muyAlta = entryGrams(en) >= MAX_GRAMOS_ENTRADA;
                return (
                  <div key={en.id} id={'entrada-' + en.id} className={`relative rounded-xl transition-shadow duration-700 ${recien.includes(en.id) ? 'ring-2 ring-emerald-400' : ''}`}>
                    <div className="absolute inset-0 bg-red-500 rounded-xl flex items-center justify-end pr-4 overflow-hidden">
                      <Trash2 size={16} className="text-zinc-950" />
                    </div>
                    <div
                      className="relative bg-zinc-950 border border-zinc-800 rounded-xl pl-2.5 pr-2 py-2 flex flex-wrap items-center gap-x-2.5 gap-y-1.5"
                      style={{ transform: `translateX(${swipeDx}px)`, transition: swipeDx === 0 ? 'transform 0.2s ease' : 'none' }}
                      onTouchStart={e => onSwipeStart(en.id, e.touches[0].clientX)}
                      onTouchMove={e => onSwipeMove(en.id, e.touches[0].clientX)}
                      onTouchEnd={() => onSwipeEnd(meal, en.id)}
                    >
                      {/* El nombre necesita un mínimo de espacio: si la pantalla es
                          angosta (o la letra está grande), los botones − y + pasan
                          abajo en vez de partir el nombre a la mitad. */}
                      <div className="flex-1 min-w-[8.5rem]">
                      <button type="button" onClick={() => setEditando({ meal, id: en.id })}
                        className="w-full min-w-0 flex items-center gap-2.5 text-left">
                        <span className="w-7 h-7 rounded-full bg-zinc-900 flex items-center justify-center text-xs shrink-0">{emojiAlimento(food)}</span>
                        <span className="min-w-0">
                          <span className="block jb-body text-sm text-zinc-100 leading-snug line-clamp-2 break-words">{nombreAlimento(food)}</span>
                          <span className="block jb-body text-[11px] text-orange-400 font-semibold tabular-nums">{Math.round(m.kcal)} kcal</span>
                          {muyAlta && <span className="block text-amber-400 text-[10px]">Cantidad muy alta, revísala</span>}
                        </span>
                      </button>
                      {/* A la vista, para que el alumno sepa que puede
                          cambiar las cantidades de cada ingrediente. */}
                      {RECETAS_PLATOS[en.foodKey] && (
                        <button type="button" onClick={() => desarmarPlato(meal, en)}
                          className="ml-[38px] mt-1 jb-body text-[11px] text-orange-400 border border-orange-500/40 rounded-full px-2.5 py-0.5 hover:bg-orange-500/10">
                          🧩 Ajustar ingredientes
                        </button>
                      )}
                      </div>
                      <div className="flex items-center gap-1 shrink-0 ml-auto">
                        <BotonPaso etiqueta={`Menos ${food.name}`} onClick={() => {
                          // Ya en lo mínimo, "−" lo quita (cero): ej. el pan con
                          // pollo separado, pero sin lechuga.
                          const nueva = cambiarCantidad(porcion.qty, porcion.unit, -1);
                          if (nueva >= Number(porcion.qty)) { quitarConDeshacer(meal, en.id); return; }
                          updateEntry(meal, en.id, { unit: porcion.unit, qty: nueva, grams: undefined });
                        }}>−</BotonPaso>
                        <button type="button" onClick={() => setEditando({ meal, id: en.id })}
                          className="jb-body text-[11px] text-zinc-200 text-center w-[58px] leading-tight tabular-nums">
                          {textoPorcion(porcion)}
                        </button>
                        <BotonPaso etiqueta={`Más ${food.name}`} onClick={() => updateEntry(meal, en.id, { unit: porcion.unit, qty: cambiarCantidad(porcion.qty, porcion.unit, 1), grams: undefined })}>+</BotonPaso>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
        );
      })}

      <AguaFila mealPlan={mealPlan} setMealPlan={setMealPlan} peso={peso} />

      <div className="bg-zinc-900 border border-orange-500/30 rounded-2xl p-5">
        <h3 className="jb-display text-sm text-zinc-200 mb-3">TOTAL DEL DÍA VS. OBJETIVO</h3>
        <CalorieStatus consumed={totals.kcal} target={mealPlan.targetKcal} />
        <div className="grid grid-cols-4 gap-3 text-center">
          {[
            ['Kcal', totals.kcal, mealPlan.targetKcal],
            ['Proteína g', totals.protein, objP],
            ['Carbos g', totals.carbs, objC],
            ['Grasas g', totals.fat, objF],
          ].map(([label, val, obj]) => (
            <div key={label}>
              <div className="jb-display text-2xl text-orange-500"><AnimatedNumber value={Math.round(val)} /></div>
              <div className="text-zinc-500 text-xs">{label}</div>
              <div className="text-zinc-600 text-[11px] mt-0.5">obj. {Math.round(obj)} ({val - obj >= 0 ? '+' : ''}{Math.round(val - obj)})</div>
            </div>
          ))}
        </div>
      </div>

      {goalMismatch && (
        <div className="bg-amber-950/40 border border-amber-800/50 rounded-xl p-3 flex items-center gap-3">
          <AlertTriangle className="text-amber-500 shrink-0" size={16} />
          <p className="text-amber-200 text-xs jb-body flex-1">Tu meta de comidas ({Math.round(mealPlan.targetKcal)} kcal) no coincide con tu objetivo ({Math.round(targets.kcal)} kcal).</p>
          <button onClick={applyGoal} className={btnPrimary + ' text-xs py-1.5 px-3 shrink-0'}>Usar mi objetivo</button>
        </div>
      )}

      <RestriccionesCard mealPlan={mealPlan} setMealPlan={setMealPlan} />

      <WhatCanIEat mealPlan={mealPlan} setMealPlan={setMealPlan} username={username} remaining={{
        kcal: mealPlan.targetKcal - totals.kcal,
        protein: objP - totals.protein,
        carbs: objC - totals.carbs,
        fat: objF - totals.fat,
      }} />

      <RestaurantesAliadosCard mealPlan={mealPlan} setMealPlan={setMealPlan} />
    </div>
  );
}

