/* Eliminar cuenta — requisito de Google Play: el usuario debe poder
   solicitar la eliminación de su propia cuenta desde dentro de la
   app, sin depender del administrador. Borra las mismas tablas que
   ya cubre la política de privacidad. */
function EliminarCuentaModal({ username, onClose, onEliminado }) {
  const [paso, setPaso] = useState(1);
  const [confirmacion, setConfirmacion] = useState('');
  const [borrando, setBorrando] = useState(false);
  const [error, setError] = useState('');

  async function confirmarBorrado() {
    if (confirmacion.trim().toUpperCase() !== 'ELIMINAR') {
      setError('Escribe la palabra ELIMINAR tal cual, en mayúsculas, para confirmar.');
      return;
    }
    setBorrando(true);
    setError('');
    try {
      // El servidor borra sus datos y también su acceso (correo y contraseña).
      const { data: { session } } = await supabase.auth.getSession();
      const r = await fetch('/api/eliminar-cuenta', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${session?.access_token || ''}` },
        body: JSON.stringify({ username }),
      });
      const d = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(d.error || '');
      await supabase.auth.signOut().catch(() => {});
      onEliminado();
    } catch (e) {
      setError('No se pudo eliminar la cuenta. Intenta de nuevo o escríbenos por WhatsApp: ' + (e.message || ''));
      setBorrando(false);
    }
  }

  return (
    <div className="fixed inset-0 bg-black/70 flex items-end sm:items-center justify-center z-50 sm:px-4">
      <div className="max-h-[90vh] overflow-y-auto pb-[max(1.5rem,env(safe-area-inset-bottom))] sm:pb-6 bg-zinc-900 border border-red-500/40 rounded-t-3xl sm:rounded-2xl p-6 max-w-md w-full">
        <AsaHoja />
        {paso === 1 ? (
          <>
            <h3 className="jb-display text-lg text-red-400 mb-3">¿Eliminar tu cuenta?</h3>
            <p className="jb-body text-sm text-zinc-300 mb-3">
              Esto borra permanentemente tu cuenta, tu historial de comidas, tu plan de alimentación,
              tus fotos de progreso y tus notificaciones guardadas. <strong className="text-white">No se puede deshacer.</strong>
            </p>
            <p className="jb-body text-xs text-zinc-500 mb-5">
              Si solo quieres pausar tu cuenta (por ejemplo, mientras juntas para renovar), no hace falta eliminarla —
              tu información se queda guardada igual esperándote.
            </p>
            <div className="flex gap-2">
              <button onClick={onClose} className={btnGhost + ' flex-1'}>Cancelar</button>
              <button onClick={() => setPaso(2)} className="flex-1 bg-red-600 hover:bg-red-500 text-white rounded-lg py-2.5 jb-body text-sm">
                Sí, continuar
              </button>
            </div>
          </>
        ) : (
          <>
            <h3 className="jb-display text-lg text-red-400 mb-3">Última confirmación</h3>
            <p className="jb-body text-sm text-zinc-300 mb-3">
              Escribe <strong className="text-white">ELIMINAR</strong> para confirmar que quieres borrar tu cuenta para siempre.
            </p>
            <input autoComplete="off" value={confirmacion} onChange={e => setConfirmacion(e.target.value)}
              className={inputCls + ' w-full mb-2'} placeholder="ELIMINAR" autoFocus />
            {error && <p className="text-red-400 text-xs jb-body mb-2">{error}</p>}
            <div className="flex gap-2 mt-3">
              <button onClick={onClose} className={btnGhost + ' flex-1'} disabled={borrando}>Cancelar</button>
              <button onClick={confirmarBorrado} disabled={borrando}
                className="flex-1 bg-red-600 hover:bg-red-500 text-white rounded-lg py-2.5 jb-body text-sm flex items-center justify-center gap-2">
                {borrando ? <Loader2 className="animate-spin" size={16} /> : 'Eliminar mi cuenta'}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

function NotificacionesModal({ username, onClose }) {
  const [estado, setEstado] = useState('cargando'); // cargando | yaActivo | disponible | bloqueado | nosoportado | iosNoInstalado
  const [activando, setActivando] = useState(false);

  useEffect(() => {
    (async () => {
      const ua = window.navigator.userAgent || '';
      const esIOS = /iPad|iPhone|iPod/.test(ua) && !window.MSStream;
      const instalada = window.matchMedia('(display-mode: standalone)').matches
        || window.navigator.standalone === true;
      if (!('Notification' in window) || !('serviceWorker' in navigator) || !('PushManager' in window)) {
        setEstado(esIOS && !instalada ? 'iosNoInstalado' : 'nosoportado');
        return;
      }
      if (Notification.permission === 'denied') { setEstado('bloqueado'); return; }
      if (Notification.permission === 'granted') {
        try {
          const reg = await navigator.serviceWorker.ready;
          const sub = await reg.pushManager.getSubscription();
          setEstado(sub ? 'yaActivo' : 'disponible');
        } catch { setEstado('disponible'); }
        return;
      }
      setEstado('disponible');
    })();
  }, []);

  async function activar() {
    setActivando(true);
    try {
      const permiso = await Notification.requestPermission();
      if (permiso !== 'granted') {
        setEstado(permiso === 'denied' ? 'bloqueado' : 'disponible');
        setActivando(false);
        return;
      }
      const reg = await navigator.serviceWorker.ready;
      let sub = await reg.pushManager.getSubscription();
      if (!sub) {
        sub = await reg.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: base64ToUint8(VAPID_PUBLIC),
        });
      }
      const j = sub.toJSON();
      await supabase.from('push_subs').upsert({
        username, endpoint: j.endpoint, p256dh: j.keys.p256dh, auth: j.keys.auth, activa: true,
      }, { onConflict: 'endpoint' });
      setEstado('yaActivo');
    } catch (e) { /* si falla, se queda en el estado que corresponda */ }
    setActivando(false);
  }

  return (
    <div className="fixed inset-0 bg-black/70 flex items-end sm:items-center justify-center z-50 sm:px-4">
      <div className="max-h-[90vh] overflow-y-auto pb-[max(1.5rem,env(safe-area-inset-bottom))] sm:pb-6 bg-zinc-900 border border-orange-500/40 rounded-t-3xl sm:rounded-2xl p-6 max-w-md w-full">
        <AsaHoja />
        {estado === 'yaActivo' ? (
          <>
            <h3 className="jb-display text-lg text-emerald-400 mb-3">¡Ya están activas!</h3>
            <p className="jb-body text-sm text-zinc-300 mb-5">Jonah ya puede acompañarte con avisos.</p>
            <button onClick={onClose} className={btnPrimary + ' w-full'}>Cerrar</button>
          </>
        ) : (
          <>
            <h3 className="jb-display text-lg text-orange-500 mb-3">Activar notificaciones</h3>
            <p className="jb-body text-sm text-zinc-300 mb-4">
              Así Jonah te avisa si se te pasa una comida, te acompaña cuando lo necesites, y te avisa a tiempo antes de que venza tu plan.
            </p>
            {estado === 'bloqueado' && (
              <p className="jb-body text-xs text-red-400 bg-red-950/30 border border-red-800/40 rounded-lg p-2.5 mb-4">
                Parece que ya las bloqueaste antes. Actívalas manualmente en los ajustes de notificaciones de tu navegador para este sitio, y vuelve a intentar.
              </p>
            )}
            {estado === 'nosoportado' && (
              <p className="jb-body text-xs text-zinc-500 bg-zinc-950 border border-zinc-800 rounded-lg p-2.5 mb-4">
                Tu navegador actual no soporta notificaciones.
              </p>
            )}
            {estado === 'iosNoInstalado' && (
              <div className="jb-body text-xs text-orange-400 bg-orange-950/20 border border-orange-800/40 rounded-lg p-2.5 mb-4">
                En iPhone, primero instala la app en tu pantalla de inicio para poder recibir notificaciones.
                <BotonGuiaIphone />
              </div>
            )}
            <div className="flex gap-2">
              <button onClick={onClose} className={btnGhost + ' flex-1'} disabled={activando}>Cerrar</button>
              {estado === 'disponible' && (
                <button onClick={activar} disabled={activando} className={btnPrimary + ' flex-1'}>
                  {activando ? <Loader2 className="animate-spin" size={16} /> : 'Activar'}
                </button>
              )}
            </div>
          </>
        )}
      </div>
    </div>
  );
}

function MiCelularModal({ username, telefonoActual, onClose }) {
  const [telefono, setTelefono] = useState(telefonoActual || '');
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState('');
  const [guardado, setGuardado] = useState(false);

  async function guardar() {
    const limpio = telefono.replace(/\D/g, '');
    if (limpio.length < 9) { setError('Escribe un celular válido (9 dígitos).'); return; }
    setError('');
    setGuardando(true);
    try {
      const { error: err } = await supabase.from('alumnos').update({ telefono: limpio }).eq('username', username);
      if (err) throw err;
      setGuardado(true);
    } catch (e) {
      setError('No se pudo guardar: ' + (e?.message || 'Intenta de nuevo.'));
    }
    setGuardando(false);
  }

  return (
    <div className="fixed inset-0 bg-black/70 flex items-end sm:items-center justify-center z-50 sm:px-4">
      <div className="max-h-[90vh] overflow-y-auto pb-[max(1.5rem,env(safe-area-inset-bottom))] sm:pb-6 bg-zinc-900 border border-orange-500/40 rounded-t-3xl sm:rounded-2xl p-6 max-w-md w-full">
        <AsaHoja />
        {guardado ? (
          <>
            <h3 className="jb-display text-lg text-emerald-400 mb-3">¡Listo!</h3>
            <p className="jb-body text-sm text-zinc-300 mb-5">Tu celular quedó guardado.</p>
            <button onClick={onClose} className={btnPrimary + ' w-full'}>Cerrar</button>
          </>
        ) : (
          <>
            <h3 className="jb-display text-lg text-orange-500 mb-3">
              {telefonoActual ? 'Actualizar mi celular' : 'Agregar mi celular'}
            </h3>
            <p className="jb-body text-sm text-zinc-300 mb-4">
              Así puedo escribirte por WhatsApp cuando te haga falta un empujón, o avisarte a tiempo si tu plan está por vencer.
            </p>
            <input type="tel" inputMode="tel" value={telefono} onChange={e => setTelefono(e.target.value)}
              className={inputCls + ' w-full'} placeholder="999 888 777" autoFocus />
            {error && <p className="text-red-400 text-xs jb-body mt-2 flex items-center gap-1.5"><AlertTriangle size={12} />{error}</p>}
            <div className="flex gap-2 mt-4">
              <button onClick={onClose} className={btnGhost + ' flex-1'} disabled={guardando}>Cancelar</button>
              <button onClick={guardar} disabled={guardando} className={btnPrimary + ' flex-1'}>
                {guardando ? <Loader2 className="animate-spin" size={16} /> : 'Guardar'}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

// Tras la primera comida del día, si el alumno todavía no tiene datos u
// objetivo: ya vio que la app funciona, así que es el mejor momento para
// pedirle lo que falta para calcular su meta real.
// Primera comida en 1 toque. Casi todos los que abandonan la prueba sin
// registrar nada se van justo después de poner sus datos: ya armaron su
// plan pero nunca vieron la app funcionar. Apenas su meta está lista (datos
// + objetivo) y aún no registraron ninguna comida, se les muestra su meta y
